// ─────────────────────────────────────────────────────────────────────────────────────────────
// Bloques con comportamiento v1.18 · game.bloques
//
// El comportamiento cuelga del MATERIAL, no del voxel. Es como lo hace Minecraft: el mundo guarda
// un id de paleta por celda y el comportamiento vive en UN objeto por TIPO de bloque; el codigo de
// movimiento pregunta «que bloque toco» y lo resuelve con un indice de array (O(1), sin recorrer
// nada). Un script por voxel serian 96x48x96 = 442368 closures, que es justo lo que Minecraft evita.
//
// Se engancha en UN solo sitio: un envoltorio sobre mcUpdate (app.js:5053), que tiene una unica
// llamada (mcTick, app.js:6323). NO se toca mcSolid: lo usan tambien el mallado (app.js:4711), el
// raycast (5529) y romper/poner (5658), asi que apagarlo ahi descoseria las caras de los vecinos y
// haria desaparecer la pieza del apuntado. Por eso `atravesable` (v1.29) va por OTRA pregunta sobre
// la misma rejilla — mcSolidWalk, «¿me frena al andar?», que solo consulta el array mc.atraviesa que
// escribe este snippet. La escalera sigue siendo solida: subes PEGADO a ella.
//
// Uso:
//   game.bloques.define('hab:escalera', { trepable:true, subida:4, bajada:5 });
//   game.bloques.define('hab:placa',    { alPisar(c){ game.tp(51,20,50); } });
//   game.bloques.define('hab:hierba', { atravesable:true });   ← se ve y se rompe, pero se cruza al andar
//   game.bloques.define('asset:assets/leaves.vox.json', { luz:'pasa' });  ← la luz del cielo lo atraviesa (hojas)
//   game.bloques.info()    ← que piso / que tengo delante, con la CLAVE EXACTA para copiar
//   game.bloques.lista()   game.bloques.quitar(clave)   game.bloques.avisos()
//   game.bloques.pasoSuave(0.06)  ← el ojo alcanza al cuerpo tras un escalon (0 = como antes)
//   game.bloques.inercia(0.7)     ← lo que tarda la marcha en bajar al salir de un bloque rapido
//   game.bloques.define('hab:hielo', { deslizamiento:1.2 });  ← al soltar WASD sigues rodando
//   game.bloques.roce(0.08)       ← lo que se sigue patinando UNA VEZ FUERA del bloque deslizante
//   game.bloques.define('asset:assets/cabeza.vox.json', { mirar:{ limites:{y:[-70,70]}, alcance:12 } });
//   ...{ mirar:{ pivote:1 } }          <- el pivote nº1 DIBUJADO con la herramienta 📍 del editor
//   ...{ mirar:{ pivote:'auto' } }      <- el pivote de la cara por la que ESTA instancia esta pegada
//   ...{ mirar:{ pivotes:{ 1:{limites:{y:[-70,70]}}, 2:{limites:{y:[110,250]}} } } }  <- giros por pivote
//   ...{ mirar:{ pivote:[0.5,2,0.5] } } <- o a mano: cuelga de ESE punto suyo, no del centro de su caja
//   ...{ mirar:{ sentido:{x:-1} } }      ← al reves: invierte el cabeceo (x) o el giro (y)
//   ...{ mirar:{ frente:{x:-90} } }      ← el dibujo apunta hacia ABAJO (brazo, cañon): apunta de verdad
//   ...{ mirar:{ sinVolteo:true } }      ← antes que darse media vuelta, cabecea (piezas espejo)
//                                 ↑ la pieza gira hacia el jugador al pasar (solo estructuras)
//   game.bloques.mirones()        ← que piezas estan girando ahora mismo y cuanto
//   game.bloques.define('asset:assets/guardian.vox.json', { seguir:{ deteccion:16, distancia:2.5 } });
//                                 ↑ la pieza te PERSIGUE: arranca dentro del radio y se para a esa
//                                   distancia. Es solida donde se la ve: choca, te bloquea, te subes.
//   ...{ seguir:{ objetivo:'hab:abeja' } }  ← o persigue a OTRA PIEZA (la instancia mas cercana)
//   ...{ seguir:{ correa:24, volver:true } } ← no se aleja mas de eso del ancla, y sin nadie a la
//                                   vista se vuelve a ella
//   ...{ seguir:{ ejes:'xyz' } }    ← vuela; por defecto 'xz' va pegada al suelo
//   game.bloques.seguidores()     ← quien persigue a quien, cuanto se ha ido y por que esta parada
//   game.bloques.recoger()        ← todos a su ancla (boton de panico si una se encaja)
//   ── agentes articulados (un NPC de varias piezas que se mueven como UN cuerpo) ──────────────
//   game.esqueletos.crear(doc, x, y, z)  ← lo planta ahi de pie; devuelve una promesa con su handle
//                                 El doc dice sus piezas, donde va cada una y como articula; el
//                                 formato entero esta comentado sobre `var esqueletos` mas abajo.
//   game.esqueletos.lista()       ← que agentes hay vivos, donde estan y que estan haciendo
//   game.esqueletos.quitar()      ← se los lleva a todos (o .quitar(id) a uno)
//   game.esqueletos.empujar(id)   ← el GOLPE: sale despedido hacia atras y pega un brinco.
//                                 El clic izquierdo sobre el bicho ya hace esto; no se rompe.
//   Sus piezas son EFIMERAS: no entran en mundo.json y desaparecen al recargar la pestaña.
//   tecla X (rayos-X)             ← cada etiqueta lleva su comportamiento y sus giros X/Y/Z
// ─────────────────────────────────────────────────────────────────────────────────────────────
(function () {

  // ═════════════════════════════════════════════════════════════════════════════════════════════
  //  ESTO ES LO QUE SE EDITA A DIARIO: que hace cada material de ESTE mundo.
  //  La clave tiene que ser la EXACTA del material — sacala con game.bloques.info() estando encima.
  //  Opciones:  trepable:true + subida/bajada (u/s)   ·   impulso (u/s hacia arriba) o altura (bloques)
  //             atravesable:true  (no frena al andar; vale para terreno y para estructuras finas)
  //             velocidad (x la marcha mientras lo pisas)  ·  deslizamiento (s de patinaje al soltar)
  //             alPisar(c) (se dispara UNA vez al entrar en la celda)  ·  nota (texto para lista())
  //             mirar (la pieza gira hacia el jugador; solo estructuras, no terreno)
  //               · pivote: [x,y,z] del OBJETO (bloques desde su esquina) por donde se engancha
  //               · sentido: { x:-1 } invierte el cabeceo, { y:-1 } el giro
  //               · frente: { x:-90 } el dibujo ya apunta hacia abajo → APUNTA en vez de inclinarse
  //  Aqui solo hay DATOS: quien los registra es el bucle del final del snippet, que es donde ya
  //  existe define(). Llamar a define() aqui arriba reventaria: aun no hay ni tabla ni cache.
  var DEFECTOS = {
    'hab:escalera': { trepable: true, subida: 4, bajada: 5, nota: 'Avanza contra ella para subir, retrocede para bajar.' },
    'asset:assets/diana.vox.json': { impulso: 24 },
    'asset:assets/hielo.vox.json': { velocidad: 2, deslizamiento: 1.2 },
    'asset:assets/hielo-pista-de-patinaje.vox.json': { deslizamiento: 1.2, velocidad: 1 },
    'asset:assets/cabeza.vox.json': { mirar: { ejes: 'xy', limites: { y: [-70, 70], x: [-25, 25] }, alcance: 12 } },
    // El brazo cuelga: apunta con su eje largo hacia abajo, no con su cara. frente:{x:-90} lo
    // descuenta y entonces APUNTA al jugador a cualquier distancia. Los limites se abren hasta 180
    // para que pueda levantarse por encima de la horizontal si el jugador se le pone mas alto.
    'asset:assets/brazo.vox.json': { mirar: { ejes: 'xy', alcance: 12, pivote: 1,
    //   pivote x=1 (no 0.5): el hombro es la CARA que toca el busto, no el centro de la celda. Con
    //   0.5 el punto fijo caia medio bloque fuera y al apuntar el brazo se despegaba del cuerpo.
    //   Desde v1.16 esto se puede DIBUJAR: pon el pivote con 📍 en brazo.vox.json, guarda, y cambia
    //   esta linea por `pivote: 1` (o quitala: sin pivote se usa el primero que haya dibujado).
    //   El mismo valor vale para los dos brazos porque el pivote va en coordenadas del OBJETO y
    //   ellos estan puestos con `rot` opuesto: la misma cara suya mira al busto en los dos casos.
                                              frente: { x: -90 }, limites: { y: [-180, 180], x: [30, 90] },
                                              sinVolteo: true } }
    //   frente x=-90 es lo que ES el dibujo: un brazo colgando ya apunta 90° hacia abajo. Con -180 el
    //   cabeceo pedido era elevacion+180 (90..270), o sea SIEMPRE por encima del tope de arriba y
    //   pinzado ahi: el brazo se quedaba clavado en la horizontal y xmin no llegaba a tocarse nunca.
    //   Medido: con {x:-180} el cabeceo vale 90° a cualquier altura del jugador; con {x:-90} va
    //   59°→90°. Y el -90 honesto es ademas lo que hace que sinVolteo salga bien, porque la postura
    //   alternativa se calcula con el.
    //   sinVolteo: los dos brazos estan con `rot` opuesto, asi que apuntar la CARA de los dos al
    //   mismo sitio obliga a uno a darse media vuelta sobre si mismo — el dueño lo vio como «el brazo
    //   izquierdo gira por la espalda y acaba con los dedos del reves». Con sinVolteo ese se queda
    //   con su giro casi a cero y sube por delante: el mismo movimiento que el otro, solo cambia el
    //   lado desde el que sube.
  };
  // ═════════════════════════════════════════════════════════════════════════════════════════════
  //  De aqui abajo, la maquinaria. No hace falta tocarla para cambiar el mundo.
  // ═════════════════════════════════════════════════════════════════════════════════════════════

  var VERSION = 'v1.30';
  // MC_HW/MC_PH son `const` de app.js: se leen por la cadena de ambitos, pero no estan en window.
  // El respaldo mantiene el snippet ejecutable en pruebas headless.
  var HW = (typeof MC_HW === 'number') ? MC_HW : 0.3;   // medio ancho del jugador a escala 1
  var PH = (typeof MC_PH === 'number') ? MC_PH : 1.8;   // alto del jugador a escala 1
  var MC_T = (typeof MC_TILE === 'number') ? MC_TILE : 16;   // voxeles finos por bloque de mundo
  var ALCANCE = 0.45;                                   // cuanto se asoma el sondeo mas alla del cuerpo
  var EPS_PIE = 1 / (MC_T * 2);                         // medio voxel fino: lo justo para mirar BAJO los pies
  var GRAVEDAD = 22;                                    // la misma que app.js (mc.vel[1] -= 22*dt)
  var PASO = (typeof MC_STEP === 'number') ? MC_STEP : 0.6;   // escalon que app.js sube solo (mcMoveAxis)
  var TAU_PASO = 0.06;                                  // constante de tiempo del ojo al subir un escalon (s)
  var VEL_MAX = 40;                                     // el mismo techo que el setter de game.playerSpeed
  var TAU_INERCIA = 0.7;                                // lo que tarda la marcha en volver a la normal (s)
  var DESLIZ_DEF = 1.2;                                 // segundos de patinaje si se pide 'deslizamiento: true'
  var TAU_ROCE = 0.08;                                  // patinaje residual YA FUERA del hielo: frena casi en seco
  var DESLIZ_MIN = 0.05;                                // por debajo de esto (u/s) se apaga: andar normal no se toca

  // ── Registro: una entrada por MATERIAL ──────────────────────────────────────────────────────
  var tabla = {};       // clave ('hab:escalera') -> cfg normalizado
  var porId = [];       // cache DENSA id -> cfg. Este es el «indice de array» de Minecraft.
  var porIdLen = -1;    // longitud de mc.blockKey con la que se construyo la cache
  var tablaVer = 0;     // sube en cada define/quitar: asi 'mirar' se entera sin recorrer la tabla por frame
  var luzFirma = '';    // que ids dejaban pasar la luz la ultima vez, para no remallar el mundo sin motivo

  // La paleta solo APENDA (mcAddBlock, app.js:4358), asi que comparar la longitud basta para saber
  // si cambio. Es la misma invalidacion que usa mcXnameCache (app.js:5429).
  // El giro de una pieza vive en la CLAVE: desde que el clic derecho con R pasa por setVoxel, la celda
  // guarda una VARIANTE 'clave@n' (app.js, mcClaveConOri) en vez de estamparse como estructura suelta.
  // Es el MISMO material puesto de lado, asi que su comportamiento se busca por la clave BASE. Sin esto
  // la comparacion era exacta y una diana girada dejaba de impulsar, una escalera girada de trepar y una
  // pieza girada de dejar pasar la luz: desde fuera parecia que el comportamiento se habia perdido.
  // Una definicion explicita de la variante ('clave@1') sigue mandando sobre la del material base.
  function claveBase(k) { return k ? String(k).replace(/@\d{1,2}$/, '') : k; }
  function cfgDeClave(k) { return (k && (tabla[k] || tabla[claveBase(k)])) || null; }
  function reconstruirCache() {
    porId = [];
    // Sin un solo material que reaccione al pisarlo, la celda de los pies no se mira siquiera: es
    // aire, y preguntar por aire recorre todas las estructuras finas del mundo (claveFinaEn).
    hayPisables = Object.keys(tabla).some(function (k) { return tabla[k].alPisar || tabla[k].impulso; });
    var bk = (typeof mc !== 'undefined' && mc.blockKey) || [];
    var atrav = null;   // se crea solo si algun material es atravesable
    var luzP = null, luzIds = [];   // idem para la luz del cielo (mc.traspasaLuz)
    for (var id = 1; id < bk.length; id++) {
      var cfg = cfgDeClave(bk[id]);
      if (cfg) porId[id] = cfg;
      if (cfg && cfg.atravesable) { if (!atrav) atrav = new Uint8Array(bk.length); atrav[id] = 1; }
      // 1 = pasa, 2 = tapa. El 2 hace falta porque ahora el DEFECTO de app.js ya deja pasar la luz por los
      // bloques de recorte: sin un 'tapa' explicito no habria forma de decir 'esta vidriera SI da sombra'.
      if (cfg && (cfg.luzPasa || cfg.luzTapa)) {
        if (!luzP) luzP = new Uint8Array(bk.length);
        luzP[id] = cfg.luzPasa ? 1 : 2;
        luzIds.push(id + ':' + luzP[id]);
      }
    }
    // El gancho de app.js para los bloques de TERRENO: mc.atraviesa lo escribe este snippet y app.js solo
    // lo consulta, en mcSolidWalk y en ningun otro sitio (mcSolid NO se parchea: lo usan el mallado, el rayo
    // de apuntar y romper/poner a la vez). null mientras nadie sea atravesable = coste cero. Las estructuras
    // finas NO pasan por aqui: esas van por sinChoque, un piso mas abajo.
    if (typeof mc !== 'undefined') mc.atraviesa = atrav;
    // El otro gancho, mc.traspasaLuz (app.js, mcComputeLight/mcRelightBox). Un bloque normal TAPA la luz
    // del cielo, asi que dentro de una masa de hojas la luz vale 0 y salen NEGRAS; la MISMA pieza estampada
    // como estructura fina no ocupa la celda, deja pasar la luz y por eso se veia iluminada. Esto le da al
    // bloque el mismo trato. No abre la columna de cielo: un dosel sigue dando sombra a lo que tiene debajo.
    //
    // La firma es la lista de IDS, no el array: reconstruirCache() tambien salta cuando la paleta CRECE
    // (game.addMaterial), y comparar arrays de distinto largo daria «cambio» y relanzaria el remallado del
    // mundo entero por un material que no tiene nada que ver.
    if (typeof mc !== 'undefined') {
      var firmaLuz = luzIds.join(',');
      var cambiaLuz = firmaLuz !== luzFirma;
      mc.traspasaLuz = luzP;
      luzFirma = firmaLuz;
      // Recalcular la luz y remallar es lo mas caro de todo el snippet, asi que solo si de verdad cambia.
      if (cambiaLuz && mc.grid && typeof mcMeshAll === 'function') {
        mcMeshAll();
        // No se puede esperar: reconstruirCache() es sincrona y la llama define(). Con .catch para que un
        // fallo del re-horneado no salga como 'unhandled rejection' sin nombre.
        if (mc.structures && mc.structures.length && typeof mcRestampAll === 'function') {
          Promise.resolve(mcRestampAll()).catch(function (e) {
            console.warn('game.bloques: no he podido re-hornear las estructuras tras cambiar la luz.', e);
          });
        }
      }
    }
    porIdLen = bk.length;
    tablaVer++;
  }
  function cfgDeId(id) {
    if (!id) return null;                                // 0 = aire
    var bk = (mc && mc.blockKey) || [];
    if (porIdLen !== bk.length) reconstruirCache();
    return porId[id] || null;
  }
  // OJO: mcGetVoxel REDONDEA (app.js:6273), que no es lo que quiere una posicion continua: desde
  // x=10.6 devolveria la celda 11. Aqui se trunca, que es la celda en la que estas de verdad.
  function idEn(x, y, z) {
    x = Math.floor(x); y = Math.floor(y); z = Math.floor(z);
    if (!mc.grid || !mcInside(x, y, z)) return 0;
    return mc.grid[mcIdx(x, y, z)] || 0;
  }

  // ── Estructuras finas: la MITAD del mundo que no esta en mc.grid ─────────────────────────────
  // Un asset solo entra en la rejilla si es un 16³ MACIZO (blockLike, app.js:4006: nvox>=4096, o sea
  // hierba/roca). Cualquier cosa con forma o huecos -- una escalera de 160 voxels -- se estampa como
  // ESTRUCTURA FINA (mc.structures), con su malla propia a 1/16 de bloque y FUERA de mc.grid. Mirar
  // solo la rejilla es ver medio mundo: rayos-X lo canta («estructura · guardada · hab:escalera»).
  // Esto es mcFineBoxHit (app.js:4935) devolviendo la CLAVE en vez de un si/no, con su mismo recorte
  // por AABB (barato: las estructuras lejanas se descartan con tres comparaciones).
  function claveFinaEn(x, y, z) {
    var ests = (typeof mc !== 'undefined' && mc.structures) || null;
    if (!ests || !ests.length || typeof mcStructColl !== 'function') return null;
    var fx = Math.floor(x * MC_T), fy = Math.floor(y * MC_T), fz = Math.floor(z * MC_T);
    for (var i = 0; i < ests.length; i++) {
      var s = ests[i], g = mcStructColl(s);
      if (!g || !g.bits) continue;
      // Presencia, no choque: en una pieza atravesable `bits` son ceros a proposito, pero «que material
      // hay aqui» tiene que seguir contestando; si no, game.bloques.info() no sabria nombrar la
      // hierba que estas pisando y no habria manera de sacar su clave para definirla.
      var oc = g.bitsAim || g.bits;
      var d = g.fdim;
      var lx = fx - s.ox * MC_T; if (lx < 0 || lx >= d[0]) continue;
      var ly = fy - s.oy * MC_T; if (ly < 0 || ly >= d[1]) continue;
      var lz = fz - s.oz * MC_T; if (lz < 0 || lz >= d[2]) continue;
      if (oc[(ly * d[2] + lz) * d[0] + lx]) return s.key;
    }
    return null;
  }
  // Un punto del mundo -> que material hay ahi, venga de la rejilla o de una estructura fina.
  function materialEn(x, y, z) {
    var id = idEn(x, y, z);
    if (id) return { clave: (mc.blockKey && mc.blockKey[id]) || '?', cfg: cfgDeId(id), id: id, fina: false };
    var k = claveFinaEn(x, y, z);
    if (k) return { clave: k, cfg: tabla[k] || null, id: 0, fina: true };
    return null;
  }
  // Barrido hacia donde MIRA el jugador (sentido -1 = a su espalda), desde el borde del cuerpo hacia
  // fuera y en pasos de UN VOXEL FINO. No es un punto suelto a proposito: una escalera fina tiene
  // 1/16 de bloque de grosor y un unico sondeo casi nunca cae dentro. El coste es lineal con la
  // escala del jugador (no cubico como un barrido de AABB) y esta acotado.
  function barrer(sentido, filtro, y) {
    var p = mc.pos, esc = mc.scale || 1;
    var fx = -Math.sin(mc.yaw) * sentido, fz = -Math.cos(mc.yaw) * sentido;   // app.js:5061
    if (y == null) y = p[1] + PH * esc * 0.5;                                 // por defecto, el pecho
    var paso = 1 / MC_T, d0 = HW * esc;
    var n = Math.min(64, Math.ceil(ALCANCE * esc / paso));
    for (var i = 0; i <= n; i++) {
      var d = d0 + i * paso, x = p[0] + fx * d, z = p[2] + fz * d;
      var m = materialEn(x, y, z);
      if (m && (!filtro || filtro(m))) { m.fx = fx; m.fz = fz; m.x = x; m.y = y; m.z = z; return m; }
    }
    return null;
  }
  function esTrepable(m) { return !!(m.cfg && m.cfg.trepable); }

  // ¿Hay algo TREPABLE en la columna del cuerpo (de los pies a la cabeza) sobre el punto (x,z)?
  //
  // Se mira la altura ENTERA, no una o dos alturas sueltas, porque la escalera puede tener CUALQUIER
  // forma. La de verdad son dos largueros y peldanos cada 4 voxeles finos: a la altura del pecho hay
  // AIRE justo en los huecos entre peldanos, asi que sondear el pecho solo agarraba en los largueros
  // -- de ahi que solo se subiera «por los laterales» y en el centro el jugador se trabase.
  //
  // Barato pese a mirar mas: cada estructura se descarta consultando la TABLA antes de tocar su
  // geometria, asi que un mundo lleno de muebles no cuesta nada; solo se escanea lo ya trepable.
  function trepableEnColumna(x, z, y0, y1) {
    var by1 = Math.floor(y1);
    for (var by = Math.floor(y0); by <= by1; by++) {
      var id = idEn(x, by, z), cfg = cfgDeId(id);
      if (cfg && cfg.trepable) return { cfg: cfg, clave: (mc.blockKey && mc.blockKey[id]) || '?', fina: false };
    }
    var ests = (mc && mc.structures) || [];
    if (!ests.length || typeof mcStructColl !== 'function') return null;
    var fx = Math.floor(x * MC_T), fz = Math.floor(z * MC_T);
    var fy0 = Math.floor(y0 * MC_T), fy1 = Math.floor(y1 * MC_T);
    for (var i = 0; i < ests.length; i++) {
      var s = ests[i], c = tabla[s.key];
      if (!c || !c.trepable) continue;                    // descarte por tabla, sin mirar la malla
      var g = mcStructColl(s); if (!g || !g.bits) continue;
      var oc = g.bitsAim || g.bits;   // presencia, no choque (ver claveFinaEn)
      var d = g.fdim;
      var lx = fx - s.ox * MC_T; if (lx < 0 || lx >= d[0]) continue;
      var lz = fz - s.oz * MC_T; if (lz < 0 || lz >= d[2]) continue;
      var ly0 = Math.max(fy0 - s.oy * MC_T, 0), ly1 = Math.min(fy1 - s.oy * MC_T, d[1] - 1);
      for (var ly = ly0; ly <= ly1; ly++)
        if (oc[(ly * d[2] + lz) * d[0] + lx]) return { cfg: c, clave: s.key, fina: true };
    }
    return null;
  }
  // Barrido del agarre: hacia donde se mira, del borde del cuerpo hacia fuera, mirando en cada paso
  // la columna ENTERA del cuerpo. Los pies mandan en el remate: se trepa hasta que los pies llegan al
  // final de la escalera (quedarse 0,9 por debajo seria mas de lo que sube el auto-escalon —
  // MC_STEP=0,6, app.js:4911 — y no se podria coronar).
  function barrerAgarre() {
    var p = mc.pos, esc = mc.scale || 1;
    var fx = -Math.sin(mc.yaw), fz = -Math.cos(mc.yaw);
