  }

  // ── Avisos acotados (§22: nada de una linea por frame) ──────────────────────────────────────
  var avisos = [], vistos = {};
  function avisar(msg) {
    if (vistos[msg]) { vistos[msg]++; return; }           // el mismo fallo no se repite en consola
    vistos[msg] = 1;
    avisos.push(msg);
    if (avisos.length > 20) avisos.shift();
    console.warn('game.bloques · ' + msg + ' (no se repetirá; míralo con game.bloques.avisos())');
  }

  // ── Alta/baja de comportamientos ────────────────────────────────────────────────────────────
  function clavesConocidas() {
    var out = [], i;
