    for (i = 1; i < bk.length; i++) if (bk[i] && out.indexOf(bk[i]) < 0) out.push(bk[i]);
    var cat = (mc && mc.catalog) || [];
    for (i = 0; i < cat.length; i++) if (cat[i] && cat[i].key && out.indexOf(cat[i].key) < 0) out.push(cat[i].key);
    var ests = (mc && mc.structures) || [];   // lo ya estampado, aunque no este en la galeria abierta
    for (i = 0; i < ests.length; i++) if (ests[i] && ests[i].key && out.indexOf(ests[i].key) < 0) out.push(ests[i].key);
