  function normalizarMirar(clave, m) {
    if (m === undefined || m === null || m === false) return null;
    if (m === true) m = {};
    if (typeof m !== 'object') {
      console.warn('game.bloques.define("' + clave + '"): mirar es un objeto '
        + '{ objetivo, ejes, limites, alcance, suavidad } (o true para el valor por defecto).');
      return false;
    }
    // Tiene que ser una ESTRUCTURA (lo que estampas desde la barra y se dibuja instancia a instancia),
    // y eso no se ve en el prefijo: el mundo del dueño esta lleno de estructuras 'hab:'. Se mira si hay
    // alguna viva con esa clave, igual que hace resolver(). Sin estructuras no hay contra que validar.
    var ests = (typeof mc !== 'undefined' && mc.structures) || [];
    if (ests.length) {
      var esEstructura = false;
      for (var i = 0; i < ests.length; i++) if (ests[i] && ests[i].key === clave) { esEstructura = true; break; }
      if (!esEstructura) {
        console.warn('game.bloques.define("' + clave + '"): mirar solo funciona en ESTRUCTURAS, y "' + clave
          + '" no lo es (o no hay ninguna puesta). Un material de terreno esta fundido en la malla de su '
          + 'chunk junto a miles de celdas mas: no se puede girar una sola.');
        return false;
      }
    }
    var ejes = String(m.ejes || 'y').toLowerCase().split('').sort().join('');   // 'xy' e 'yx' son lo mismo
    if (ejes !== 'y' && ejes !== 'xy') {
      console.warn('game.bloques.define("' + clave + '"): ejes de mirar admite "y" (girar) o "xy" '
        + '(girar + cabecear). El alabeo ("z") no esta: nadie mira a nada rodando de lado.');
      return false;
