    if (obj !== 'jugador' && !(Array.isArray(obj) && obj.length >= 3
        && isFinite(obj[0]) && isFinite(obj[1]) && isFinite(obj[2]))) {
      console.warn('game.bloques.define("' + clave + '"): objetivo de mirar es "jugador" o un punto [x,y,z].');
      return false;
    }
    // pivote: por donde se engancha. Sin el, la pieza gira sobre el centro de su caja, que para un
    // brazo de dos bloques cae en el codo y no en el hombro.
    //
    // Cuatro formas, de la mas comoda a la mas manual:
    //   (nada)          <- si el DIBUJO trae pivotes puestos con la herramienta 📍, el PRIMERO
    //   pivote: 'auto'  <- el de la cara por la que ESTA instancia esta pegada a algo (ver autoPivote)
    //   pivote: 2       <- el nº2 de los dibujados (el mismo numero que el editor pinta encima)
    //   pivote: [x,y,z] <- a mano, en coordenadas del OBJETO (bloques desde su esquina)
