          || !isFinite(pv[0]) || !isFinite(pv[1]) || !isFinite(pv[2])) {
        console.warn('game.bloques.define("' + clave + '"): pivote es "auto", el NUMERO de un pivote '
          + 'dibujado en el editor (1 = el primero) o [x,y,z] en coordenadas del OBJETO: bloques desde su '
          + 'esquina, 1 bloque = 16 voxels del dibujo. Un brazo de 1x2x1 que cuelga del hombro es '
          + '[0.5, 2, 0.5]. Sin pivote se usa el 1º dibujado, y si no hay ninguno, el centro de su caja.');
        return false;
      } else {
        piv = [num(pv[0], 0), num(pv[1], 0), num(pv[2], 0)];
      }
    }
    // sentido: 1 o -1 por eje. 'mirar' apunta la CARA de la pieza (su -Z) al objetivo, pero un
    // brazo que cuelga apunta con su eje LARGO (su -Y): el mismo cabeceo que le sube la cara a una
    // cabeza le aparta la punta al brazo, asi que con el jugador por debajo del hombro — el caso
    // normal, andando por el suelo — el brazo se iba hacia atras. El dueño lo reporto asi.
    // Admite tambien la forma YA normalizada (senX/senY), como `pivote` y `limites`: reejecutar
    // el snippet re-define desde la tabla, y sin esto un { x:-1 } escrito a mano se perdia.
    var sen = (m.sentido && typeof m.sentido === 'object') ? m.sentido : { x: m.senX, y: m.senY };
    var senX = (sen.x === undefined) ? 1 : num(sen.x, 0);
    var senY = (sen.y === undefined) ? 1 : num(sen.y, 0);
    if ((senX !== 1 && senX !== -1) || (senY !== 1 && senY !== -1)) {
      console.warn('game.bloques.define("' + clave + '"): sentido es { x:1|-1, y:1|-1 } e invierte '
        + 'el cabeceo (x) o el giro (y). Una pieza que apunta con su eje largo en vez de con su cara '
