    if (sinVolteo && ejes !== 'xy') {
      console.warn('game.bloques.define("' + clave + '"): sinVolteo necesita ejes:"xy". Sin cabeceo '
        + 'no hay con que compensar la media vuelta: la pieza apuntaria al lado contrario.');
