      limX: rango(lim.x, -90, 90),
      alcance: Math.abs(num(m.alcance, 24)),   // mas lejos que esto vuelve a su pose y se apaga
      suavidad: Math.max(0, num(m.suavidad, 0.15)),  // segundos en recorrer ~2/3 del giro (0 = instantaneo)
      frente: frenteY,                         // grados: hacia donde mira ya el dibujo, en horizontal
      frenteX: frenteX,                        // grados: y en vertical (-90 = apunta hacia abajo)
      piv: piv,                                // enganche en coordenadas del objeto (null = su centro)
      pivNum: pivNum,                          // nº de pivote DIBUJADO pedido (0 = «el 1º, si lo hay»)
      pivAuto: pivAuto,                        // true: lo elige la cara pegada, instancia a instancia
      vars: variantes,                         // { nº: config } giros/limites propios de cada pivote
      sinVolteo: sinVolteo,                    // true: prefiere cabecear antes que darse media vuelta
