  // ── 'seguir': la pieza se DESPLAZA hacia algo ───────────────────────────────────────────────
  // 'mirar' gira la pieza sin moverla de sitio; esto la mueve. Y el sitio de una estructura es
  // s.ox/oy/oz, que NO se puede tocar: es lo que mcSerialize escribe en mundo.json (app.js:6333) y
  // lo que al cargar se trunca con |0 (app.js:6358), asi que mover el ancla dejaria la pieza a
  // saltos de bloque y guardaria una posicion que el dueño no puso. Asi que el desplazamiento vive
  // en la MISMA matriz s.model que usa 'mirar' (traslacion en la ultima columna) y el ancla se
  // queda donde estaba. Consecuencia buscada: al recargar el mundo la pieza vuelve a su ancla.
  //
  // La solidez NO sale gratis de ahi: la colision fina sondea el bitset con base s.ox (app.js:5063)
  // y no mira s.model, asi que una pieza movida por matriz seria un fantasma. Se arregla envolviendo
  // el sondeo (ver «Solidez de los seguidores» mas abajo), no tocando app.js.
  function normalizarSeguir(clave, g) {
    if (g === undefined || g === null || g === false) return null;
    if (g === true) g = {};
    if (typeof g !== 'object') {
      console.warn('game.bloques.define("' + clave + '"): seguir es un objeto '
        + '{ objetivo, deteccion, distancia, velocidad, correa, volver, ejes, suavidad } (o true).');
      return false;
