    // instancia mas cercana de esa clave, que es lo que hace que una pieza pueda seguir a otra.
    var obj = (g.objetivo === undefined) ? 'jugador' : g.objetivo;
    var porClave = false;
    if (obj !== 'jugador') {
      if (Array.isArray(obj) && obj.length >= 3 && isFinite(obj[0]) && isFinite(obj[1]) && isFinite(obj[2])) {
        obj = [num(obj[0], 0), num(obj[1], 0), num(obj[2], 0)];
      } else if (typeof obj === 'string') {
        var res = resolver(obj);   // admite nombre corto igual que define(); reresolver ya resuelto no cambia nada
        if (res.error) {
          console.warn('game.bloques.define("' + clave + '"): objetivo de seguir — ' + res.error);
          return false;
        }
        obj = res.clave; porClave = true;
      } else {
        console.warn('game.bloques.define("' + clave + '"): objetivo de seguir es "jugador", '
          + 'un punto [x,y,z], o la clave de otro material (seguira a su instancia mas cercana).');
        return false;
      }
    }
    var ejes = String(g.ejes || 'xz').toLowerCase().split('').sort().join('');
    if (ejes !== 'xz' && ejes !== 'xyz') {
      console.warn('game.bloques.define("' + clave + '"): ejes de seguir admite "xz" (pegada al suelo) '
        + 'o "xyz" (vuela). Perseguir solo en un eje no es perseguir.');
      return false;
    }
