      + ' (~' + (Math.round(cfg.impulso * cfg.impulso / (2 * GRAVEDAD) * 10) / 10) + ' bloques)');
    if (cfg.velocidad) partes.push('velocidad ×' + cfg.velocidad +
      ' (' + (Math.round(Math.min(VEL_MAX, mc.speed * cfg.velocidad) * 10) / 10) + ' u/s)');
    if (cfg.deslizamiento) partes.push('deslizamiento ' + cfg.deslizamiento + 's');
    if (cfg.atravesable) partes.push('atravesable');
