      + (cfg.mirar.pivAuto ? ', pivote automático (la cara pegada manda)' : '')
      + (cfg.mirar.vars ? ', ' + Object.keys(cfg.mirar.vars).length + ' pivote(s) con giros propios' : '')
      + (cfg.mirar.senX < 0 ? ', cabeceo invertido' : '') + (cfg.mirar.senY < 0 ? ', giro invertido' : '') + ')');
