      + ' (para a ' + cfg.seguir.distancia + ', ve a ' + (cfg.seguir.deteccion || '∞')
      + ', ' + cfg.seguir.velocidad + ' bl/s, ' + cfg.seguir.ejes
      + (cfg.seguir.correa ? ', correa ' + cfg.seguir.correa : ', sin correa')
