      var L = cfg.mirar, a = s.aabb;
      // El pivote puede ser cosa de la INSTANCIA (pivote:'auto') y cada uno traerse sus propios
      // giros y limites. Se resuelve una vez y se cachea EN LA INSTANCIA, nunca en una lista
      // aparte: mcRestampAll desestampa y vuelve a estampar todas al cargar, asi que una lista
      // cacheada acabaria poniendole la matriz a piezas muertas — es el fallo de «la cabeza no me
      // mira al cargar, solo si reejecuto el snippet». Si no toca nada por una cara con pivote,
      // cae al nº1, que es lo mismo que hace no poner pivote.
      if (L.porPivote) {
        if (s._pivAuto === undefined) s._pivAuto = L.pivAuto ? (autoPivote(s, L) || 1) : (L.pivNum || 1);
        L = L.porPivote[s._pivAuto] || L;
      }
      if (!a) continue;                  // instancia a medio construir: se la salta, no se tumba el frame
      // Por donde se engancha: el centro de su caja salvo que la config diga otra cosa. El punto
      // que sale de aqui es el UNICO que no se mueve al girar, asi que es literalmente la
      // articulacion.
      var px, py, pz;
      if (L.piv) { puntoPivote(a, s.rot & 3, L.piv, pivXYZ); px = pivXYZ[0]; py = pivXYZ[1]; pz = pivXYZ[2]; }
      else { px = (a[0] + a[3]) * 0.5; py = (a[1] + a[4]) * 0.5; pz = (a[2] + a[5]) * 0.5; }
      var tx, ty, tz;
      if (L.objetivo === 'jugador') { tx = p[0]; ty = p[1]; tz = p[2]; }
      else { tx = L.objetivo[0]; ty = L.objetivo[1]; tz = L.objetivo[2]; }
      var dx = tx - px, dy = ty - py, dz = tz - pz;
      var horiz = Math.sqrt(dx * dx + dz * dz);
      // El angulo se mide DESDE la pose ya horneada (yaw = rot&3, cuartos de vuelta), que es lo que
      // hace que 'limites' signifique «grados desde su orientacion de origen» y no desde el norte.
      var horneado = (s.rot & 3) * 90 + L.frente;
      // «No mirar» tiene DOS motivos y los dos acaban igual: la pieza vuelve a su pose de origen.
      // El segundo se olvidaba, y se quedaba clavada en su tope mirando a la pared para siempre.
      var giroObj = 0, cabObj = 0;
      var dist2 = horiz * horiz + dy * dy;
      var rendida = dist2 > L.alcance * L.alcance;                         // 1) demasiado lejos
      // Por que se rinde, para que la etiqueta de rayos-X lo pueda decir. Son dos numeros y no una
      // cadena a proposito: esto corre por pieza y frame, y componer texto ahi seria basura por frame.
      // 0 = esta girando · 1 = fuera de alcance (_mirarPide = distancia) · 2 = fuera del cono
      // (_mirarPide = los grados que PEDIRIA girar, que es justo lo que hay que comparar con limites).
      s._mirarPor = rendida ? 1 : 0;
      s._mirarPide = rendida ? Math.sqrt(dist2) : 0;
      if (!rendida) {
        var crudo = wrap180((Math.atan2(dx, -dz) / GRADO - horneado) * L.senY);
        // Media vuelta o cabeceo: las dos posturas apuntan igual, asi que se coge la que deja la
        // pieza mas cerca de su orientacion de origen. La banda muerta (80/100 en vez de 90 pelado)
        // es para que plantarse justo en el limite no la haga aletear entre las dos.
        var volteada = false;
        if (L.sinVolteo) {
          volteada = Math.abs(crudo) > (s._mirarVolteada ? 80 : 100);
          if (volteada) crudo = wrap180(crudo + 180);
        }
        s._mirarVolteada = volteada;
        giroObj = pinza(crudo, L.limY[0], L.limY[1]);
        // 2) no puede girar tanto: le has salido por detras. Quedarse en el tope es la postura de un
        // maniqui; rendirse y volver a su sitio es lo que hace un cuello.
        if (giroObj !== crudo) { rendida = true; giroObj = 0; s._mirarPor = 2; s._mirarPide = crudo; }
        // El CABECEO no se cuenta como rendirse: llegar al tope del cuello mirando hacia arriba es
        // seguir mirandote, y si contara, pegar un salto le apagaria la cabeza entera de golpe.
        else if (L.ejes === 'xy') {
          // El cabeceo se PINZA en la postura de siempre y se convierte DESPUES. Asi 'limites.x'
          // significa «cuanto levanta el brazo» para los dos brazos por igual, y no una cosa en uno
          // y su negativa en el otro: los dos suben lo mismo, cada uno desde su lado.
          cabObj = pinza(Math.atan2(dy, horiz) / GRADO * L.senX - L.frenteX, L.limX[0], L.limX[1]);
          if (volteada) cabObj = wrap180(180 - cabObj - 2 * L.frenteX);
        }
      }
      // Suavizado exponencial (mismo criterio que el resto del snippet: exp(-dt/tau), o sea igual a
      // 30 que a 120 fps). El giro se interpola por el camino CORTO, si no, ir de 179 a -179 daria
      // una vuelta entera de mas justo cuando pasas por detras.
      var k = L.suavidad > 0 ? 1 - Math.exp(-dt / L.suavidad) : 1;
      var giro = (typeof s._mirarYaw === 'number') ? s._mirarYaw + wrap180(giroObj - s._mirarYaw) * k : giroObj;
      var cab = (typeof s._mirarPit === 'number') ? s._mirarPit + (cabObj - s._mirarPit) * k : cabObj;
      giro = wrap180(giro);          // acotado: si no, dar vueltas lo aleja de sus 'limites' para siempre
      s._mirarYaw = giro; s._mirarPit = cab;
      // Ya rendida y ya en reposo: se quita la matriz en vez de dejar una identidad puesta, y
      // asi app.js vuelve a su camino de siempre (sin uniform y sin inflar la caja de culling).
      if (rendida && Math.abs(giro) < 0.05 && Math.abs(cab) < 0.05) {
        s._mirarYaw = 0; s._mirarPit = 0;
        if (desplazada(s)) matrizTraslacion(matrizDe(s), s._sig.x, s._sig.y, s._sig.z);
        else if (s.model) s.model = null;
        continue;
      }
      var m = matrizDe(s);
      matrizGiro(m, giro * GRADO, cab * GRADO, horneado * GRADO, px, py, pz);
      // Girar alrededor del pivote y DESPUES trasladar: sumar en la ultima columna es exactamente
      // T·R. Al reves (trasladar y luego girar) la pieza orbitaria el pivote en vez de perseguir.
      if (desplazada(s)) { m[12] += s._sig.x; m[13] += s._sig.y; m[14] += s._sig.z; }
    }
  }
  function mirones_() {
    var filas = mirones.map(function (s) {
      return { clave: s.key, celda: s.ox + ',' + s.oy + ',' + s.oz,
               giro: Math.round(s._mirarYaw || 0) + '°',
               cabeceo: Math.round(s._mirarPit || 0) + '°',
               activa: !!s.model };
    });
    if (!filas.length) console.log('game.bloques: ninguna pieza tiene "mirar" (o el Mundo no esta abierto).');
    else if (console.table) console.table(filas); else console.log(filas);
    return filas;
  }
  function seguidores_() {
    var filas = seguidores.map(function (s) {
      var g = s._sig || { x: 0, y: 0, z: 0, por: 0, pide: 0 };
      var G = (tabla[s.key] || {}).seguir;
      return { clave: s.key, ancla: s.ox + ',' + s.oy + ',' + s.oz,
               desplazada: (Math.round(g.x * 10) / 10) + ',' + (Math.round(g.y * 10) / 10) + ',' + (Math.round(g.z * 10) / 10),
               lejos: Math.round(Math.sqrt(g.x * g.x + g.y * g.y + g.z * g.z) * 10) / 10,
               objetivo: G ? aQuien(G) : '?',
               a: Math.round(g.pide * 10) / 10,
               estado: POR_SIG[g.por],
               solida_donde_se_ve: !!(g.x || g.y || g.z) };
    });
    if (!filas.length) console.log('game.bloques: ninguna pieza tiene "seguir" (o el Mundo no esta abierto).');
    else if (console.table) console.table(filas); else console.log(filas);
    return filas;
  }

  // ═════════════════════════════════════════════════════════════════════════════════════════════
  //  AGENTES ARTICULADOS: un ESQUELETO de piezas que se mueven como UN cuerpo
  // ═════════════════════════════════════════════════════════════════════════════════════════════
  // Por que esto no es una entrada mas de `tabla`: la tabla es por MATERIAL y un rig es por
  // INSTANCIA. Los dos brazos de un zombie son el mismo material y tienen que ir en OPOSICION; con
  // 'seguir' por material cada uno perseguiria por su cuenta y los dos acabarian amontonados en el
  // mismo punto. Asi que los esqueletos viven en su propio registro, con sus piezas ya estampadas.
  //
  // Cuatro cosas que hay que saber para leer lo de abajo:
  //
  // 1. LAS PIEZAS SON EFIMERAS. Se estampan con `quiet` (ni historial ni guardado) y llevan
  //    `s.efimera`, que mcSerialize salta (app.js). Un agente invocado en vivo NO deja rastro en
  //    mundo.json y desaparece al recargar. Es la consecuencia buscada, no un descuido.
  //
  // 2. LA CELDA ES ENTERA Y EL CUERPO NO. mcStampStruct coloca en coordenadas de BLOQUE, pero un
  //    brazo tiene que ir a 0,3125 bloques del costado. Asi que cada pieza se estampa en la celda
  //    REDONDEADA y el resto fraccionario (`o`) viaja en la matriz. Consecuencia: una pieza de rig
  //    SIEMPRE lleva matriz, tambien parada — quitarsela la devolveria de golpe a su celda. Por eso
  //    aqui no hay el `s.model = null` en reposo que si tiene 'mirar'.
  //
  // 3. HAY DOS CENTROS DE GIRO. El cuerpo gira sobre SU eje vertical y la extremidad cabecea sobre
  //    SU hombro; con una sola matriz, girar el cuerpo 90° despega los brazos del torso. Asi que:
  //        M = T(desplazamiento) · Ryaw(cuerpo, eje de la raiz) · T(o) · Rart(articulacion, pivote)
  //    Un unico producto 4x4 por pieza y frame (multiplicar), sobre buffers reusados.
  //
  // 4. LA PERSECUCION NO SE REIMPLEMENTA. La raiz llama a pasoSeguir(), la misma que usa 'seguir'.
  //    Lo unico que cambia es la caja: se le pasa la del CUERPO entero, no la del torso.
  //
  // El documento de un agente (lo mismo que guardara data/agentes/*.json en la fase 2):
  //
  //   {
  //     nombre: 'Zombie',
  //     raiz:   { pieza:'asset:assets/torso-zombie.vox.json', rot:0 },
  //     piezas: [
  //       // `en` = donde va la ESQUINA BAJA de la pieza, en bloques, desde la esquina de la raiz.
  //       // Ejes del mundo: [x, alto, z]. La z negativa es hacia DELANTE (a donde mira el agente).
  //       { nombre:'cabeza', pieza:'asset:assets/cabeza-zombie.vox.json', en:[-0.09,0.88,-0.22],
  //         mirar:{ limites:{ y:[-70,70] }, alcance:12 } },        // gira hacia el jugador
  //       { nombre:'brazo izq', pieza:'asset:assets/brazo-zombie.vox.json', en:[-0.31,0,0.09],
  //         articula:{ pivote:2, base:85, amplitud:10, fase:0 } }, // 85° = levantado hacia delante
  //       ...
  //     ],
  //     seguir: { deteccion:14, distancia:1.2, velocidad:2.2 },    // lo mismo que game.bloques
  //     cuerpo: { ancho:0.65, alto:2.55 },                         // la caja con la que CHOCA
  //     andar:  { cadencia:0.7, suavidad:0.12 },                   // ciclos de paso por bloque
  //     empuje: { fuerza:8, freno:0.15, salto:4.5 },               // el GOLPE: cuanto sale despedido
  //     fisica: { peso:1, caida:12 }                               // PISA COMO TU (ver normalizarFisica)
  //   }
  //
  // En `articula`:  pivote = el nº de un pivote DIBUJADO con 📍 (1 = el primero) o [x,y,z] en
  // coordenadas del objeto; sin el, la pieza gira sobre el centro de su caja.  base = los grados
  // que mantiene mientras PERSIGUE.  reposo = los que mantiene parado (0 = como esta dibujada).
  // amplitud = el vaiven.  fase = el desfase dentro del ciclo (dos piernas: 0 y 180).
  // eje = 'x' cabecea (lo normal: un brazo, una pierna) · 'y' gira sobre la vertical.
  // ⚠️ El signo: POSITIVO es hacia DELANTE, hacia donde mira el agente. Un brazo colgando esta a 0
  // y a 90 esta horizontal apuntandote. Es la unica convencion que hay que recordar.
  var esqueletos = [];                 // los vivos; se heredan al reejecutar el snippet
  var esqSeq = 0;
  var mYaw = new Float32Array(16), mLoc = new Float32Array(16);   // se reusan: nada de basura por frame
  var pivEsq = [0, 0, 0];
  var CERO = [0, 0, 0];               // el `o` de una pieza posada: sin celda, no hay resto que corregir
  var docsCache = {};                  // clave -> doc del dibujo, solo para leer sus pivotes al crear

  // Producto de dos matrices 4x4 en el orden de columnas de WebGL: out = a·b (primero b). `out` no
  // puede ser `a` ni `b`. Existe por el punto 3 de arriba y por nada mas.
  function multiplicar(out, a, b) {
    for (var c = 0; c < 4; c++) {
      var b0 = b[c * 4], b1 = b[c * 4 + 1], b2 = b[c * 4 + 2], b3 = b[c * 4 + 3];
      out[c * 4]     = a[0] * b0 + a[4] * b1 + a[8]  * b2 + a[12] * b3;
      out[c * 4 + 1] = a[1] * b0 + a[5] * b1 + a[9]  * b2 + a[13] * b3;
      out[c * 4 + 2] = a[2] * b0 + a[6] * b1 + a[10] * b2 + a[14] * b3;
      out[c * 4 + 3] = a[3] * b0 + a[7] * b1 + a[11] * b2 + a[15] * b3;
    }
  }

  // El punto sobre el que gira una pieza, en coordenadas de mundo SIN desplazar: su pivote si lo
  // trae y, si no, el centro de su caja. Lo consultan dos sitios — el angulo de la mirada y la
  // matriz — y tienen que dar lo MISMO: si la cabeza mide su angulo desde el centro de la caja y
  // luego gira sobre el cuello, apunta sistematicamente un poco al lado y el fallo solo se ve de
  // cerca. Escribe en `salida` y la devuelve: cero basura por pieza y frame.
  function centroGiro(aa, rot, piv, salida) {
    if (piv) { puntoPivote(aa, rot & 3, piv, salida); return salida; }
    salida[0] = (aa[0] + aa[3]) * 0.5;
    salida[1] = (aa[1] + aa[4]) * 0.5;
    salida[2] = (aa[2] + aa[5]) * 0.5;
    return salida;
  }

  // La matriz de UNA pieza:  m = mYaw · T(o) · Rart(articulacion, sobre SU pivote).
  // Falta el T(g) del desplazamiento del agente, que lo suma quien llame (el bicho vivo) o nadie
  // (el preview del editor, que dibuja el agente quieto en el origen).
  // Esta funcion es la unica que sabe componer una pieza, y a proposito: la anima el zombie del
  // Mundo y la dibuja el panel del editor, y si cada uno se hiciera la suya el preview enseñaria
  // un bicho que no es el que luego anda por ahi. No toca `mc` ni el reloj — solo cuentas.
  function matrizPieza(m, mYawIn, aa, rot, piv, art, o, giroMira, fase, activo, andando) {
    var c = centroGiro(aa, rot, piv, pivEsq);
    var giroL = 0, cabL = 0;
    if (art) {
      // ⚠️ DOS INTERRUPTORES DISTINTOS, y confundirlos se ve enseguida:
      //   · `activo` = TE VE → la POSE (los brazos en alto son `base`; al perderte bajan a `reposo`).
      //   · `andando` = SE MUEVE → el VAIVEN.
      // Con el vaiven colgado de `activo`, al volverse a su sitio dejaba de verte y se iba
      // deslizando de lado con las piernas rectas, como un mueble empujado.
      var ang = art.reposo + (art.base - art.reposo) * activo
              + art.amplitud * andando * Math.sin(fase + art.fase * GRADO);
      if (art.eje === 'y') giroL = ang; else cabL = ang;
    }
    giroL += giroMira || 0;   // la mirada ya viene RELATIVA al giro del cuerpo (la calcula quien llama)
    matrizGiro(mLoc, giroL * GRADO, cabL * GRADO, (rot & 3) * 90 * GRADO, c[0], c[1], c[2]);
    mLoc[12] += o[0]; mLoc[13] += o[1]; mLoc[14] += o[2];   // sumar en la ultima columna es T(o)·M
    multiplicar(m, mYawIn, mLoc);
  }

  // El dibujo de una pieza, para sacarle los pivotes. Se pide UNA vez por clave y al CREAR, nunca
  // por frame. La cache muere con esta ejecucion del snippet: si repones los pivotes con 📍, basta
  // con volver a ejecutarlo.
  function docDe(clave) {
    if (Object.prototype.hasOwnProperty.call(docsCache, clave)) return Promise.resolve(docsCache[clave]);
    if (typeof getRoomData !== 'function') return Promise.resolve(null);
    return getRoomData(clave).then(function (d) { return (docsCache[clave] = d || null); },
                                   function () { return (docsCache[clave] = null); });
  }

  function normalizarArticulacion(art) {
    if (!art) return null;
    var eje = String(art.eje || 'x').toLowerCase();
    return {
      pivote: (art.pivote === undefined) ? null : art.pivote,
      base: num(art.base, 0), reposo: num(art.reposo, 0),
      amplitud: num(art.amplitud, 0), fase: num(art.fase, 0),
      eje: (eje === 'y') ? 'y' : 'x'
    };
  }
  // Ojo al nombre: normalizarMirar (sin 'da') es la de 'mirar' por material y son cosas distintas —
  // esta es mucho mas corta porque un rig ya sabe donde tiene el pivote y hacia donde mira el cuerpo.
  function normalizarMirada(m) {
    if (!m) return null;
    var lim = (m.limites && m.limites.y) || [-70, 70];
    return { alcance: Math.abs(num(m.alcance, 12)),
             limY: [num(lim[0], -70), num(lim[1], 70)],
             suavidad: Math.abs(num(m.suavidad, 0.12)) };
  }

  // ── El almacen: data/agentes/*.json ──────────────────────────────────────────────────────────
  // Ojo a la pareja de nombres, que no son sinonimos: `game.agentes` son los DOCUMENTOS guardados
  // en disco (que bichos sabemos hacer) y `game.esqueletos` es lo VIVO en este mundo (que bichos
  // hay ahora mismo y donde). Guardar un agente no planta nada; plantar uno no guarda nada.
  //
  // El documento se guarda TAL CUAL, con las claves que traiga: el servidor solo le impone `id` y
  // `savedAt`. Asi, ampliar el formato mas adelante no rompe los agentes ya guardados ni los
  // vacia al volver a guardarlos desde una version vieja del panel.
  function agentesLista() {
    return fetch('/api/agentes', { cache: 'no-store' })
      .then(function (r) { return r.ok ? r.json() : []; })
      .catch(function () { console.warn('game.agentes.lista: no he podido hablar con el servidor.'); return []; });
  }

  function agenteCargar(id) {
    id = String(id || '').trim();
    if (!id) { console.warn('game.agentes.cargar: dime el id del agente (game.agentes.lista()).'); return Promise.resolve(null); }
    return fetch('/api/agentes/' + encodeURIComponent(id), { cache: 'no-store' })
      .then(function (r) {
        if (r.ok) return r.json();
        console.warn('game.agentes.cargar: no hay ningun agente "' + id + '". game.agentes.lista() dice cuales hay.');
        return null;
      })
      .catch(function () { console.warn('game.agentes.cargar: no he podido hablar con el servidor.'); return null; });
  }

  function agenteGuardar(doc) {
    if (!doc || typeof doc !== 'object' || !doc.raiz || !doc.raiz.pieza || !Array.isArray(doc.piezas)) {
      console.warn('game.agentes.guardar: dame un documento { nombre, raiz:{pieza}, piezas:[...] }.');
      return Promise.resolve(null);
    }
    return fetch('/api/agentes', { method: 'POST', headers: { 'Content-Type': 'application/json' },
                                   body: JSON.stringify(doc) })
      .then(function (r) { return r.ok ? r.json() : null; })
      .then(function (res) {
        if (!res) { console.warn('game.agentes.guardar: el servidor lo ha rechazado.'); return null; }
        console.log('game.agentes: guardado "' + res.id + '".');
        return res;
      })
      .catch(function () { console.warn('game.agentes.guardar: no he podido hablar con el servidor.'); return null; });
  }

  // ── Crear ────────────────────────────────────────────────────────────────────────────────────
  // (x,y,z) es la celda donde se PLANTA: el agente queda de pie con los pies en su suelo. Devuelve
  // una promesa porque estampar y leer los dibujos van por red.
  //
  // `def` puede ser el documento entero o, mas comodo, el ID de uno guardado: crear('zombie', ...).
  // Lo segundo es lo que evita que el mismo bicho acabe descrito en dos sitios a la vez.
  function crearEsqueleto(def, x, y, z) {
    if (typeof def === 'string') {
      return agenteCargar(def).then(function (doc) { return doc ? crearEsqueleto(doc, x, y, z) : null; });
    }
    if (!def || typeof def !== 'object' || !def.raiz || !def.raiz.pieza || !Array.isArray(def.piezas)) {
      console.warn('game.esqueletos.crear: dame un documento { raiz:{pieza}, piezas:[...], seguir:{...} } '
        + 'o el id de uno guardado (game.agentes.lista()).');
      return Promise.resolve(null);
    }
    if (typeof mc === 'undefined' || !mc.grid || typeof mcStampStruct !== 'function') {
      console.warn('game.esqueletos.crear: el Mundo no está abierto (esto solo va en la pestaña del Mundo).');
      return Promise.resolve(null);
    }
    x = Math.round(num(x, 0)); y = Math.round(num(y, 0)); z = Math.round(num(z, 0));

    // La raiz es la pieza 0 y su `en` es [0,0,0] por definicion: todo lo demas se mide desde ella.
    var brutas = [{ nombre: def.raiz.nombre || 'raíz', pieza: def.raiz.pieza, rot: def.raiz.rot, en: [0, 0, 0] }];
    for (var i = 0; i < def.piezas.length; i++) {
      var q = def.piezas[i];
      if (!q || !q.pieza) { console.warn('game.esqueletos.crear: la pieza nº' + (i + 1) + ' no dice qué material es.'); return Promise.resolve(null); }
      brutas.push(q);
    }
    // Los PIES: la pieza que baja mas. Asi (x,y,z) significa «plantado aqui» y no «con el torso aqui».
    var pies = 0;
    for (i = 0; i < brutas.length; i++) {
      var e = brutas[i].en || [0, 0, 0];
      if (num(e[1], 0) < pies) pies = num(e[1], 0);
    }
    var baseY = y - pies;                       // altura (fraccionaria) de la esquina de la raiz

    var rig = {
      id: ++esqSeq, nombre: def.nombre || ('agente ' + esqSeq), def: def,
      partes: [], quitado: false,
      giro: 0, fase: 0, activo: 0, andando: 0,
      cadencia: Math.abs(num(def.andar && def.andar.cadencia, 0.7)),
      suavidad: Math.abs(num(def.andar && def.andar.suavidad, 0.12)),
      mov: null,   // lo que el cuerpo lleva encima (golpe, bote, caida, patinaje); null = pegado al suelo
      fis: normalizarFisica(def.fisica),   // pisar como el jugador; null = a su bola (fisica:false)
      pisada: '', marcha: [0, 0],          // el flanco del trampolin y la marcha REAL (para el hielo)
      empFuerza: Math.abs(num(def.empuje && def.empuje.fuerza, EMP_FUERZA)),
      empFreno: Math.abs(num(def.empuje && def.empuje.freno, EMP_FRENO)),
      empSalto: Math.abs(num(def.empuje && def.empuje.salto, EMP_SALTO)),
      horneado: 0, eje: [0, 0, 0], cuerpo: null, G: null, plantado: [x, y, z]
    };

    // Una promesa por pieza, en cadena: mcStampStruct puede disparar un mcRestampAll (si el atlas
    // crece) y hacerlas en paralelo dejaria a medias las anteriores.
    var cadena = Promise.resolve(), o0 = null;
    brutas.forEach(function (q, idx) {
      cadena = cadena.then(function () {
        var en = q.en || [0, 0, 0];
        var P = [x + num(en[0], 0), baseY + num(en[1], 0), z + num(en[2], 0)];
        var cel = [Math.round(P[0]), Math.round(P[1]), Math.round(P[2])];
        var res = [P[0] - cel[0], P[1] - cel[1], P[2] - cel[2]];
        if (idx === 0) o0 = res;                // el resto de la RAIZ viaja en _sig, no en la matriz:
        // asi golpe()/envAt (que solo saben de _sig) la ven solida EXACTAMENTE donde se la dibuja.
        var parte = {
          nombre: q.nombre || ('pieza ' + idx), clave: q.pieza, rot: (q.rot | 0) & 15,
          cel: cel, o: [res[0] - o0[0], res[1] - o0[1], res[2] - o0[2]],
          piv: null, art: normalizarArticulacion(q.articula), mirar: normalizarMirada(q.mirar),
          giroMira: 0, s: null, idx: -1
        };
        rig.partes.push(parte);
        return docDe(parte.clave).then(function (doc) {
          // El pivote, a coordenadas del OBJETO. Se resuelve UNA vez, aqui, y no por frame.
          var pv = parte.art && parte.art.pivote;
          if (pv !== null && pv !== undefined) {
            if (Array.isArray(pv)) parte.piv = [num(pv[0], 0), num(pv[1], 0), num(pv[2], 0)];
            else {
              parte.piv = doc ? pivoteDeDibujo(doc, Math.round(num(pv, 1))) : null;
              if (!parte.piv) console.warn('game.esqueletos.crear: "' + parte.nombre + '" pide el pivote nº'
                + pv + ' y ese dibujo no lo trae. Ponlo con la herramienta 📍 del editor; mientras tanto '
                + 'girará sobre el centro de su caja.');
            }
          }
          return mcStampStruct(parte.clave, cel[0], cel[1], cel[2], parte.rot, true);
        }).then(function () {
          // mcStampStruct no devuelve la instancia, y ademas puede haberla sustituido por el camino
          // (mcRestampAll). Se coge la ULTIMA que case, que es la recien puesta.
          var ests = mc.structures;
          for (var j = ests.length - 1; j >= 0; j--) {
            var s = ests[j];
            if (s.key === parte.clave && s.ox === cel[0] && s.oy === cel[1] && s.oz === cel[2]
                && (s.rot | 0) === parte.rot && !s._rig) { parte.s = s; parte.idx = j; break; }
          }
          if (!parte.s) { console.warn('game.esqueletos.crear: no encuentro la pieza recién puesta "' + parte.clave + '".'); return; }
          parte.s.efimera = true;               // NO entra en mundo.json (mcSerialize la salta)
          parte.s._rig = rig;
          if (idx === 0) parte.s._rigRaiz = true;
        });
      });
    });

    return cadena.then(function () {
      var R = rig.partes[0];
      if (!R || !R.s || !R.s.aabb) { quitarEsqueleto(rig); return null; }
      rig.horneado = (R.s.rot & 3) * 90;
      var ra = R.s.aabb;
      rig.eje = [(ra[0] + ra[3]) * 0.5, (ra[1] + ra[4]) * 0.5, (ra[2] + ra[5]) * 0.5];
      // La caja con la que CHOCA. Por defecto la union de las piezas, pero un zombie con los brazos
      // en cruz mide 1,4 de ancho y entonces no cabe por una puerta: por eso el documento puede
      // pedir una caja esbelta, como la del jugador, que es lo que hace falta para andar por ahi.
      var b = [Infinity, Infinity, Infinity, -Infinity, -Infinity, -Infinity];
      for (var i = 0; i < rig.partes.length; i++) {
        var P = rig.partes[i], aa = P.s && P.s.aabb; if (!aa) continue;
        for (var k = 0; k < 3; k++) {
          if (aa[k] + P.o[k] < b[k]) b[k] = aa[k] + P.o[k];
          if (aa[k + 3] + P.o[k] > b[k + 3]) b[k + 3] = aa[k + 3] + P.o[k];
        }
      }
      var C = def.cuerpo;
      if (C) {
        var hw = Math.abs(num(C.ancho, 0.6)) * 0.5, hd = Math.abs(num(C.fondo, num(C.ancho, 0.6))) * 0.5;
        var alto = Math.abs(num(C.alto, b[4] - b[1]));
        b = [rig.eje[0] - hw, b[1], rig.eje[2] - hd, rig.eje[0] + hw, b[1] + alto, rig.eje[2] + hd];
      }
      rig.cuerpo = b;
      if (def.seguir === false || def.seguir === null) {
        console.warn('game.esqueletos.crear: un agente sin `seguir` se quedaría plantado para siempre '
          + 'y no haría falta ningún rig. Ponle al menos { deteccion, distancia, velocidad }.');
        quitarEsqueleto(rig); return null;
      }
      rig.G = normalizarSeguir(R.s.key, def.seguir === undefined ? true : def.seguir);
      if (!rig.G) { quitarEsqueleto(rig); return null; }
      if (rig.G.porClave) {
        console.warn('game.esqueletos.crear: un esqueleto todavía no sabe perseguir a otro material; '
          + 'perseguirá al jugador.');
        rig.G = normalizarSeguir(R.s.key, { deteccion: rig.G.deteccion, distancia: rig.G.distancia,
          velocidad: rig.G.velocidad, correa: rig.G.correa, volver: rig.G.volver, ejes: rig.G.ejes,
          suavidad: rig.G.suavidad });
        if (!rig.G) { quitarEsqueleto(rig); return null; }
      }
      // _sig arranca con el resto fraccionario de la raiz: a partir de aqui, «donde esta el agente»
      // es una sola cosa (el _sig) y la solidez sale gratis de los envoltorios de v1.18.
      R.s._sig = { x: o0[0], y: o0[1], z: o0[2], por: 1, pide: 0 };
      esqueletos.push(rig);
      console.log('game.esqueletos: ' + rig.nombre + ' (#' + rig.id + ') plantado en ' + x + ',' + y + ',' + z
        + ' · ' + rig.partes.length + ' piezas efímeras (no entran en el mundo)');
      return rig;
    });
  }

  // ── Quitar ───────────────────────────────────────────────────────────────────────────────────
  function quitarEsqueleto(rig) {
    if (!rig) return 0;
    var n = 0;
    for (var i = 0; i < rig.partes.length; i++) {
      var s = rig.partes[i].s;
      if (!s) continue;
      s._rig = null; s._rigRaiz = false; s._sig = null; s.model = null;
      if (typeof mcRemoveStruct === 'function' && mc.structures.indexOf(s) >= 0) { mcRemoveStruct(s, true); n++; }
      rig.partes[i].s = null;
    }
    rig.quitado = true;
    var j = esqueletos.indexOf(rig); if (j >= 0) esqueletos.splice(j, 1);
    return n;
  }

  // ── Re-adquirir: mc.structures no guarda los MISMOS objetos ──────────────────────────────────
  // mcRestampAll y mcRebakeStructsNear sustituyen cada instancia por una NUEVA en el mismo indice
  // (app.js). Un rig que se fie de sus referencias acaba animando piezas muertas mientras las vivas
  // se quedan plantadas en su celda — es el mismo fallo de «la cabeza no me mira al cargar». Se
  // re-adquiere primero por INDICE (que se conserva en la sustitucion) y, si ya no vale porque
  // alguien borro otra estructura y el array se corrio, por (clave, celda, rot) sin repetir
  // instancia: dos piezas iguales en la misma celda tienen que salir distintas.
  function casaParte(s, P) {
    return !!s && s.key === P.clave && s.ox === P.cel[0] && s.oy === P.cel[1] && s.oz === P.cel[2]
        && (s.rot | 0) === P.rot;
  }
  function readquirir(rig) {
    var ests = mc.structures, ps = rig.partes;
    for (var i = 0; i < ps.length; i++) {
      var P = ps[i], s = ests[P.idx];
      if (s && s === P.s) continue;                     // lo normal: nada ha cambiado, coste cero
      if (!casaParte(s, P)) {
        s = null;
        for (var j = 0; j < ests.length; j++) {
          var e = ests[j];
          if (!casaParte(e, P)) continue;
          var tomada = false;
          for (var k = 0; k < ps.length; k++) if (k !== i && ps[k].s === e) { tomada = true; break; }
          if (!tomada) { s = e; P.idx = j; break; }
        }
      }
      if (!s) { if (P.s) { P.s._rig = null; P.s._rigRaiz = false; } P.s = null; continue; }
      var sigViejo = P.s && P.s._sig;
      if (P.s && P.s !== s) { P.s._rig = null; P.s._rigRaiz = false; }
      P.s = s; s._rig = rig; s.efimera = true;
      if (i === 0) { s._rigRaiz = true; if (sigViejo && !s._sig) s._sig = sigViejo; }
    }
  }

  // ── El GOLPE: le pegas y sale despedido ───────────────────────────────────
  // No es un teletransporte sino una VELOCIDAD que se frena sola, y de ahi salen gratis las dos
  // cosas que hacen que parezca un golpe de Minecraft: si detras hay una pared se para contra ella
  // (mismo paso eje a eje que andar, con su asentar()) y el bicho vuelve solo, porque el que
  // persigue sigue persiguiendo mientras sale despedido.
  //
  // El brinco NO puede ser un g.y a secas: en 'xz' la Y de la raiz la REESCRIBE asentar() desde el
  // suelo cada vez que la pieza se mueve. Va aparte, en `alto` (altura sobre el suelo), se descuenta
  // antes de andar y se vuelve a sumar despues; dejandolo puesto se acumularia en los frames en que
  // el bicho esta quieto y el zombie acabaria en el cielo.
  var EMP_FUERZA = 8, EMP_FRENO = 0.15, EMP_SALTO = 4.5;
  // La gravedad del bicho es la MISMA que la tuya (GRAVEDAD, la de app.js). No es cosmetico: si
  // fuera otra, un trampolin de impulso 24 te subiria 13 bloques y a el 14, y el mundo tendria dos
  // fisicas distintas segun quien lo pise.

  // ── La fisica del suelo, para el agente ──────────────────────────────────────────────────────
  // Todo lo que game.bloques.define pone en un material (velocidad, deslizamiento, impulso...)
  // estaba escrito SOLO para el jugador: vive en los envoltorios de mcPlayerStep y toca mc.speed,
  // mc.vel[1] y mc._deslizVel. Un agente no pasa por ahi — se movia a velocidad fija y pegado al
  // suelo, asi que sobre hielo iba igual de lento y el trampolin no le hacia nada.
  //
  // Aqui se lee la MISMA tabla desde los pies del bicho. Va encendida por defecto: un agente que
  // ignora el suelo que pisa es el fallo, no la conducta normal. `fisica:false` la apaga entera.
  //
  // ⚠️ `alPisar` NO se dispara, y a proposito: el alPisar que hay escrito esta pensado para el
  // jugador (hace game.tp), asi que un zombie pisando una placa te teletransportaria A TI. Se
  // enciende con fisica:{placas:true} a sabiendas de que el alPisar sepa quien pisa.
  function normalizarFisica(f) {
    if (f === false || f === null) return null;
    if (f === undefined || f === true) f = {};
    if (typeof f !== 'object') {
      console.warn('game.esqueletos: fisica es un objeto { marcha, desliza, impulso, cae, placas, '
        + 'peso, caida } o false para apagarla entera.');
      f = {};
    }
    return {
      marcha: f.marcha !== false,             // el suelo le cambia la velocidad (hielo x2, barro x0.5)
      desliza: f.desliza !== false,           // sigue rodando al dejar de andar sobre algo deslizante
      impulso: f.impulso !== false,           // el trampolin lo lanza
      cae: f.cae !== false,                   // se cae por los bordes en vez de quedarse clavado
      placas: !!f.placas,                     // alPisar: apagado a proposito (ver arriba)
      peso: Math.abs(num(f.peso, 1)) || 1,    // divide el impulso: un bicho pesado bota menos
      caida: Math.max(0, num(f.caida, 12))    // bloques que se atreve a bajar; mas alla se queda al borde
    };
  }
  // Que material pisa el agente: medio voxel fino BAJO su caja, en el centro de la huella. Es
  // pieEn() con la caja del bicho en vez de la del jugador, y con la misma identidad de FLANCO
  // (celda + clave), que es lo que evita que quedarse encima de un trampolin sea un motor infinito.
  function sueloDe(a, g) {
    var x = (a[0] + a[3]) * 0.5 + g.x, y = a[1] + g.y - EPS_PIE, z = (a[2] + a[5]) * 0.5 + g.z;
    var m = (typeof mc !== 'undefined' && mc.grid) ? materialEn(x, y, z) : null;
    return { cfg: m ? m.cfg : null,
             id: Math.floor(x) + ',' + Math.floor(y) + ',' + Math.floor(z) + '|' + (m ? m.clave : '') };
  }
  // asentar() pega la raiz al suelo de su nueva columna DE GOLPE. Ese salto hacia abajo se convierte
  // en altura sobre el suelo: la posicion que se ve no cambia este frame y la gravedad la baja en
  // los siguientes. O sea que el bicho se CAE por el borde en vez de teletransportarse al fondo.
  function caerDesde(rig, yAntes, g) {
    if (!rig.fis || !rig.fis.cae) return;
    var bajada = yAntes - g.y;
    if (bajada > 1e-3) nuevoMov(rig).alto += bajada;
  }
  function nuevoMov(rig) {
    return rig.mov || (rig.mov = { vx: 0, vz: 0, vy: 0, alto: 0, freno: rig.empFreno });
  }
  // Mover la raiz por las bravas, con la misma colision que un paso normal (y el mismo truco de
  // pasar g.x como xPrev en el segundo eje: si la Z no cabe, la X que si cabia se conserva).
  function moverRaiz(s, a, g, dx, dz, drop) {
    var x0 = g.x, z0 = g.z, ok = true;
    if (dx) { g.x += dx; if (!asentar(s, a, g, x0, z0, drop)) ok = false; }
    if (dz) { g.z += dz; if (!asentar(s, a, g, g.x, z0, drop)) ok = false; }
    return ok;
  }
  function empujarEsqueleto(rig, fuerza, dx, dz) {
    if (!rig || rig.quitado) return false;
    var n = Math.sqrt(dx * dx + dz * dz);
    if (!(n > 1e-6)) return false;                        // sin direccion no hay empujon
    var f = num(fuerza, 0) > 0 ? num(fuerza, 0) : rig.empFuerza;
    var e = nuevoMov(rig);
    e.vx = dx / n * f; e.vz = dz / n * f; e.freno = rig.empFreno;   // un golpe manda sobre el patinaje

    if (e.alto <= 1e-4) e.vy = rig.empSalto;              // el brinco solo desde el suelo: pegarle en el aire no lo encadena
    return true;
  }
  // Un frame de lo que el cuerpo lleva encima, con la raiz ya asentada por pasoSeguir. Un solo
  // canal para las cuatro cosas que lo mueven sin que el ande: el golpe, el bote del trampolin, la
  // caida por un borde y el patinaje sobre hielo. Devuelve la altura sobre el suelo.
  function movPaso(rig, s, g, dt) {
    var e = rig.mov;
    if (!e) return 0;
    var drop = rig.fis ? rig.fis.caida : 0, yAntes = g.y;
    if ((e.vx || e.vz) && !moverRaiz(s, rig.cuerpo, g, e.vx * dt, e.vz * dt, drop)) { e.vx = 0; e.vz = 0; }
    caerDesde(rig, yAntes, g);                           // si esto lo ha sacado por un borde, se cae
    var fr = e.freno > 0 ? Math.exp(-dt / e.freno) : 0;
    e.vx *= fr; e.vz *= fr;
    e.vy -= GRAVEDAD * dt;
    e.alto += e.vy * dt;
    if (e.alto <= 0) { e.alto = 0; e.vy = 0; }            // ha aterrizado
    if (!e.alto && Math.abs(e.vx) + Math.abs(e.vz) < 0.05) { rig.mov = null; return 0; }
    return e.alto;
  }
  // La fisica del suelo, un frame. Va DESPUES de andar: el trampolin lanza, el borde tira y el
  // hielo hace patinar, y las tres cosas salen por el mismo canal que el golpe (rig.mov).
  function fisicaPaso(rig, s, g, dt, pie, xAntes, zAntes) {
    var F = rig.fis, cfg = pie.cfg, enSuelo = !rig.mov || rig.mov.alto <= 1e-4;
    // Trampolin, en el FLANCO igual que pisar(): quedarse encima no vuelve a lanzarlo. Estando en
    // el aire no se apunta la pisada, asi que caer sobre uno SI lo lanza al aterrizar.
    if (enSuelo) {
      if (F.impulso && cfg && cfg.impulso && rig.pisada !== pie.id) nuevoMov(rig).vy = cfg.impulso / F.peso;
      rig.pisada = pie.id;
    }
    // Patinaje. Para el jugador esto se cuenta como «al soltar las teclas sigues rodando», porque
    // el jugador va a teclazos; un agente no suelta nada, su persecucion ya frena sola y suavemente,
    // asi que ese enunciado no se le nota. Es lo mismo dicho al reves y es lo que hace el hielo de
    // Minecraft: sobre algo deslizante la marcha REAL persigue con retardo `tau` a la que la
    // persecucion pide, asi que ni arranca de golpe ni para de golpe — y de ahi sale el resbalon
    // al llegar. `marcha` es la de verdad; `pedida` la que salio de pasoSeguir.
    //
    // Fuera del hielo el retardo es CERO y entonces marcha = pedida y el ajuste es exactamente
    // cero: la conducta de v1.25 no cambia ni un voxel donde no hay nada deslizante.
    if (!F.desliza || dt <= 0) return;
    var m = rig.marcha, px = (g.x - xAntes) / dt, pz = (g.z - zAntes) / dt;
    var tau = (cfg && cfg.deslizamiento) || 0;
    if (tau <= 0) { m[0] = px; m[1] = pz; return; }
    var k = 1 - Math.exp(-dt / tau);
    m[0] += (px - m[0]) * k; m[1] += (pz - m[1]) * k;
    var ex = (m[0] - px) * dt, ez = (m[1] - pz) * dt;     // lo que le sobra (o le falta) a ese paso
    if (Math.abs(ex) + Math.abs(ez) < DESLIZ_MIN * dt) return;
    var yAntes = g.y;
    if (!moverRaiz(s, rig.cuerpo, g, ex, ez, F.caida)) { m[0] = px; m[1] = pz; }  // contra un muro se para
    caerDesde(rig, yAntes, g);                            // ...y si el resbalon lo saca por un borde, cae
  }
  // El golpe sale del JUGADOR: se empuja en la direccion jugador→agente medida EN PLANTA. Con la
  // direccion de la mirada saldria casi igual de frente y de lado al pegarle de refilon.
  function golpear(rig, fuerza) {
    var R = rig && rig.partes[0], s = R && R.s, a = s && s.aabb;
    if (!a || typeof mc === 'undefined' || !mc.pos) return false;
    var g = s._sig || { x: 0, y: 0, z: 0 };
    return empujarEsqueleto(rig, fuerza,
      (a[0] + a[3]) * 0.5 + g.x - mc.pos[0],
      (a[2] + a[5]) * 0.5 + g.z - mc.pos[2]);
  }
  function rigDe(rig) {
    if (rig && typeof rig === 'object') return rig.quitado ? null : rig;
    var enc = null;
    esqueletos.forEach(function (r) { if (r.id === (rig | 0)) enc = r; });
    return enc;
  }

  // ── El paso, por frame ───────────────────────────────────────────────────────────────────────
  function esqueletosPaso(dt) {
    if (!esqueletos.length || typeof mc === 'undefined' || !mc.structures || !mc.pos) return;
    var p = mc.pos;
    for (var r = 0; r < esqueletos.length; r++) {
      var rig = esqueletos[r];
      if (rig.quitado) continue;
      readquirir(rig);
      var R = rig.partes[0], sr = R.s;
      // Sin raiz no hay agente. Y si la raiz falta pero sus MIEMBROS siguen ahi, es que alguien se
      // ha llevado el cuerpo por su cuenta (un script, un clic de una version vieja): lo que queda
      // son cinco piezas congeladas en el aire, peor que ninguna, asi que se retiran y el agente se
      // da de baja. Ojo con la condicion: durante un mcRestampAll faltan TODAS a la vez, y ahi no
      // hay nada que hacer — el rig las re-adquiere solas cuando vuelven.
      if (!sr || !sr.aabb) {
        var sueltas = 0;
        for (var q = 1; q < rig.partes.length; q++) if (rig.partes[q].s) sueltas++;
        if (!sr && sueltas) {
          avisar('el agente "' + rig.nombre + '" se ha quedado sin cuerpo: se retiran sus ' + sueltas + ' pieza(s) sueltas');
          quitarEsqueleto(rig); r--;
        }
        continue;
      }
      var g = sr._sig || (sr._sig = { x: 0, y: 0, z: 0, por: 1, pide: 0 });
      var G = rig.G, hay = true, tx = 0, ty = 0, tz = 0;
      if (G.objetivo === 'jugador') { tx = p[0]; ty = p[1]; tz = p[2]; }
      else { tx = G.objetivo[0]; ty = G.objetivo[1]; tz = G.objetivo[2]; }

      // 1. Andar. La caja que se mueve es la del CUERPO, no la del torso. El brinco del empujon se
      //    descuenta ANTES: la Y de la raiz la resuelve asentar() desde el SUELO, y solo cuando la
      //    pieza se mueve, asi que si se dejara puesto se iria acumulando.
      if (rig.mov) g.y -= rig.mov.alto;
      var gx0 = g.x, gz0 = g.z, gy0 = g.y;
      // El material que PISA: el hielo le acelera la marcha y el barro se la come, igual que a ti.
      // Se lee ANTES de andar (es el suelo del que sale el paso) y se reusa en fisicaPaso.
      var pie = rig.fis ? sueloDe(rig.cuerpo, g) : null;
      var mar = (pie && rig.fis.marcha && pie.cfg && pie.cfg.velocidad) ? pie.cfg.velocidad : 1;
      pasoSeguir(sr, rig.cuerpo, g, G, dt, hay, tx, ty, tz,
                 rig.fis ? { fac: mar, drop: rig.fis.caida } : null);
      caerDesde(rig, gy0, g);                    // ha andado hasta un borde: que se caiga, no que baje

      // 2. El ciclo de andar avanza con la DISTANCIA RECORRIDA, no con el reloj. Con el reloj, un
      //    zombie frenado contra una pared seguiria pedaleando en el sitio; asi las piernas se paran
      //    solas cuando el cuerpo no avanza, sin una sola condicion especial.
      var avance = Math.sqrt((g.x - gx0) * (g.x - gx0) + (g.z - gz0) * (g.z - gz0));
      rig.fase = (rig.fase + avance * rig.cadencia * 2 * Math.PI) % (2 * Math.PI);
      // `por` = 1 es «fuera de alcance»; 0/2/3 es «te ve» (persiguiendo, con la correa tensa o
      // bloqueada). Ese es el interruptor entre estar parado y estar en faena.
      var k = rig.suavidad > 0 ? 1 - Math.exp(-dt / rig.suavidad) : 1;
      rig.activo += ((g.por === 1 ? 0 : 1) - rig.activo) * k;
      if (rig.activo < 1e-3) rig.activo = 0;
      // Y APARTE: si SE ESTA MOVIENDO. No es lo mismo que «te ve» — al perderte, `volver` lo lleva
      // de vuelta a su ancla, y ahi sigue caminando aunque ya no persiga a nadie.
      rig.andando += ((dt > 0 && avance / dt > 0.15 ? 1 : 0) - rig.andando) * k;
      if (rig.andando < 1e-3) rig.andando = 0;

      // 2.b El empujon, DESPUES de medir el avance a proposito: salir despedido no le hace pedalear
      //     las piernas, que a un bicho al que acaban de pegar no le toca ir andando.
      if (rig.fis) fisicaPaso(rig, sr, g, dt, pie, gx0, gz0);
      if (rig.mov) g.y += movPaso(rig, sr, g, dt);

      // 3. El cuerpo gira hacia el objetivo, medido desde la pose ya horneada (igual que 'mirar').
      //    Y si no persigue pero anda (volviendose a su sitio), mira HACIA DONDE VA: si no, se va
      //    de lado o de espaldas, que es lo que delata que esto es un muñeco y no un bicho.
      //    Parado y sin objetivo se queda como este: nada de desgirarse solo hacia el norte.
      var cxr = rig.eje[0] + g.x, czr = rig.eje[2] + g.z;
      var giroObj = rig.giro;
      if (g.por !== 1 && hay) giroObj = wrap180(Math.atan2(tx - cxr, -(tz - czr)) / GRADO - rig.horneado);
      else if (avance > 1e-4) giroObj = wrap180(Math.atan2(g.x - gx0, -(g.z - gz0)) / GRADO - rig.horneado);
      rig.giro = wrap180(rig.giro + wrap180(giroObj - rig.giro) * k);

      // 4. Una matriz por pieza: M = T(g) · Ryaw · T(o) · Rart.
      matrizGiro(mYaw, rig.giro * GRADO, 0, rig.horneado * GRADO, rig.eje[0], rig.eje[1], rig.eje[2]);
      for (var i = 0; i < rig.partes.length; i++) {
        var P = rig.partes[i], s = P.s, aa = s && s.aabb;
        if (!aa) continue;
        if (P.mirar) {
          // RELATIVO al giro del cuerpo: el cuerpo ya se ha girado hacia ti, y si esto no lo
          // descontase el giro se sumaria dos veces y la cabeza acabaria mirando de lado.
          // Va ANTES de componer, porque el resultado entra en la matriz de esta misma vuelta.
          var L = P.mirar, cp = centroGiro(aa, s.rot, P.piv, pivEsq);
          var ddx = tx - (cp[0] + g.x), ddy = ty - (cp[1] + g.y), ddz = tz - (cp[2] + g.z);
          var obj = 0;
          if (hay && (ddx * ddx + ddy * ddy + ddz * ddz) <= L.alcance * L.alcance) {
            obj = pinza(wrap180(Math.atan2(ddx, -ddz) / GRADO - (s.rot & 3) * 90 - rig.giro), L.limY[0], L.limY[1]);
          }
          var kc = L.suavidad > 0 ? 1 - Math.exp(-dt / L.suavidad) : 1;
          P.giroMira = wrap180(P.giroMira + wrap180(obj - P.giroMira) * kc);
        }
        var m = matrizDe(s);
        matrizPieza(m, mYaw, aa, s.rot, P.piv, P.art, P.o, P.giroMira, rig.fase, rig.activo, rig.andando);
        m[12] += g.x; m[13] += g.y; m[14] += g.z;                     // ...y esto, T(g)·(lo de antes)
      }
    }
  }

  // ── La POSE, para quien quiera DIBUJAR el agente sin tener un Mundo ──────────────────────────
  // El panel del editor tiene que enseñar el bicho moviendose, y la unica forma de que el preview
  // no mienta es que la pose la calcule ESTE codigo — el mismo que anima al que anda por ahi.
  // app.js solo DIBUJA lo que salga de aqui; no compone ni una matriz.
  //
  //   game.esqueletos.preparar(doc|id)  → promesa: resuelve dibujos y pivotes (eso va por red)
  //   game.esqueletos.pose(plantilla, {fase, giro, activo, andando})  → sincrono, para llamar por frame
  //
  // No toca `mc`, no estampa nada y no mira el reloj: son cuentas. Por eso funciona en la pestaña
  // del editor, donde no hay Mundo ninguno.
  //
  // Todo en BLOQUES y con la esquina de la RAIZ en el origen. Aqui NO hay celda donde redondear, asi
  // que cada pieza cae exactamente en su `en` y el `o` de la pieza viva (el resto fraccionario de
  // estampar) es cero. Es la unica diferencia geometrica con el bicho del Mundo, y va a favor: el
  // preview enseña el diseño, no el sitio donde cayo.
  //
  // ⚠️ La `fase` la pone QUIEN LLAMA, en radianes. En el Mundo avanza con la DISTANCIA recorrida
  // (por eso un zombie contra una pared deja de pedalear); un preview no anda a ningun sitio, asi
  // que ahi la mueve el reloj. La cuenta de las articulaciones es la misma en los dos casos.
  function prepararEsqueleto(def) {
    if (typeof def === 'string') {
      return agenteCargar(def).then(function (doc) { return doc ? prepararEsqueleto(doc) : null; });
    }
    if (!def || !def.raiz || !def.raiz.pieza || !Array.isArray(def.piezas)) {
      console.warn('game.esqueletos.preparar: dame un documento { raiz:{pieza}, piezas:[...] } o el id ' +
                   'de uno guardado (game.agentes.lista()).');
      return Promise.resolve(null);
    }
    var brutas = [{ nombre: def.raiz.nombre || 'raíz', pieza: def.raiz.pieza, rot: def.raiz.rot, en: [0, 0, 0] }];
    for (var i = 0; i < def.piezas.length; i++) if (def.piezas[i] && def.piezas[i].pieza) brutas.push(def.piezas[i]);
    var partes = [], cadena = Promise.resolve();
    brutas.forEach(function (q, idx) {
      cadena = cadena.then(function () {
        return docDe(String(q.pieza)).then(function (doc) {
          var c = doc ? cajaDibujo(doc) : null;
          if (!c) {
            console.warn('game.esqueletos.preparar: no encuentro el dibujo de "' + q.pieza + '" (o está vacío).');
            return;
          }
          var rot = ((q.rot | 0) % 4 + 4) % 4;       // el preview no dibuja espejados: solo los 4 cuartos
          var e = q.en || [0, 0, 0], ex = num(e[0], 0), ey = num(e[1], 0), ez = num(e[2], 0);
          var L = ladosDeDibujo(c, rot);
          var art = normalizarArticulacion(q.articula), piv = null, pv = art && art.pivote;
          if (pv !== null && pv !== undefined) {
            if (Array.isArray(pv)) piv = [num(pv[0], 0), num(pv[1], 0), num(pv[2], 0)];
            else {
              piv = pivoteDeDibujo(doc, Math.round(num(pv, 1)));
              if (!piv) console.warn('game.esqueletos.preparar: "' + (q.nombre || q.pieza) + '" pide el pivote nº'
                + pv + ' y ese dibujo no lo trae; girará sobre el centro de su caja.');
            }
          }
          partes.push({
            nombre: q.nombre || ('pieza ' + idx), clave: String(q.pieza), rot: rot,
            aa: [ex, ey, ez, ex + L[0], ey + L[1], ez + L[2]],
            lados: L, piv: piv, art: art,
            dibujo: doc,                       // va dentro para que quien dibuje no lo pida otra vez
            m: new Float32Array(16)            // suya y reusada: pose() la reescribe, no la sustituye
          });
        });
      });
    });
    return cadena.then(function () {
      if (!partes.length) { console.warn('game.esqueletos.preparar: no he podido montar ninguna pieza.'); return null; }
      var ra = partes[0].aa;
      var caja = [Infinity, Infinity, Infinity, -Infinity, -Infinity, -Infinity];
      partes.forEach(function (P) {
        for (var j = 0; j < 3; j++) {
          if (P.aa[j] < caja[j]) caja[j] = P.aa[j];
          if (P.aa[j + 3] > caja[j + 3]) caja[j + 3] = P.aa[j + 3];
        }
      });
      var pl = {
        nombre: def.nombre || 'agente', def: def, partes: partes, caja: caja,
        horneado: partes[0].rot * 90,
        eje: [(ra[0] + ra[3]) * 0.5, (ra[1] + ra[4]) * 0.5, (ra[2] + ra[5]) * 0.5]
      };
      posarEsqueleto(pl, null);            // sale ya posada en reposo: quien la pida puede dibujarla ya
      return pl;
    });
  }

  // Sincrona y sin reservar nada: reescribe la matriz que cada pieza ya tiene. Devuelve las piezas
  // (las MISMAS de la plantilla, no copias) para poder encadenar `.forEach(dibujar)`.
  function posarEsqueleto(pl, opts) {
    if (!pl || !pl.partes || !pl.partes.length) {
      console.warn('game.esqueletos.pose: dame lo que devuelve game.esqueletos.preparar(doc).');
      return [];
    }
    opts = opts || {};
    var fase = num(opts.fase, 0), giro = num(opts.giro, 0),
        activo = pinza(num(opts.activo, 0), 0, 1),
        andando = pinza(num(opts.andando, 0), 0, 1);
    matrizGiro(mYaw, giro * GRADO, 0, pl.horneado * GRADO, pl.eje[0], pl.eje[1], pl.eje[2]);
    for (var i = 0; i < pl.partes.length; i++) {
      var P = pl.partes[i];
      matrizPieza(P.m, mYaw, P.aa, P.rot, P.piv, P.art, CERO, 0, fase, activo, andando);
    }
    return pl.partes;
  }

  function esqueletos_() {
    var filas = esqueletos.map(function (rig) {
      var sr = rig.partes[0] && rig.partes[0].s, g = (sr && sr._sig) || { x: 0, y: 0, z: 0, por: 1, pide: 0 };
      return { id: rig.id, nombre: rig.nombre, piezas: rig.partes.length,
               plantado: rig.plantado.join(','),
               donde: (Math.round((rig.eje[0] + g.x) * 10) / 10) + ',' + (Math.round((rig.eje[2] + g.z) * 10) / 10),
               giro: Math.round(rig.giro) + '°', andando: Math.round(rig.andando * 100) + '%',
               teVe: Math.round(rig.activo * 100) + '%',
               a: Math.round(g.pide * 10) / 10, estado: POR_SIG[g.por],
               // Lo que no se ve en la posicion: si esta en el aire (cayendo o botando) y si algo
               // le esta empujando o haciendo patinar. Sin esto, «no llega» y «se ha caido a un
               // hoyo» se leen igual en la tabla.
               alto: rig.mov ? Math.round(rig.mov.alto * 100) / 100 : 0,
               suelto: rig.mov ? Math.round(Math.hypot(rig.mov.vx, rig.mov.vz) * 10) / 10 : 0 };
    });
    if (!filas.length) console.log('game.esqueletos: no hay ningún agente articulado vivo.');
    else if (console.table) console.table(filas); else console.log(filas);
    return filas;
  }

  // ── Subida suave de escalones: el CUERPO da el salto, el OJO lo alcanza ──────────────────────
  // app.js sube los escalones de golpe (mcMoveAxis: p[1] += h dentro del mismo frame), asi que al
  // andar por una escalera de 8 voxels la camara teletransporta y+0,5 de una vez y se ve a saltos.
  // Es lo mismo que hace Minecraft, y Minecraft lo tapa igual que aqui: la fisica NO se toca (el
  // juego sigue igual de firme, misma colision y mismo alcance de escalon), solo se PINTA al jugador
  // un poco mas abajo y ese retraso se consume en ~0,1 s.
  //
  // Como el ojo se calcula en seis sitios distintos de app.js a partir de mc.pos[1], el desfase se
  // aplica sobre mc.pos[1] al SALIR del frame y se deshace al ENTRAR en el siguiente: entre medias
  // solo hay dibujado, y toda la fisica corre siempre sobre la y de verdad.
  //
  // El estado vive en mc (no en un closure) a proposito: si se reejecuta el snippet, el envoltorio
  // nuevo hereda el desfase que dejo el viejo en vez de dejar al jugador medio bloque hundido.
  function restaurarPaso() {
    var d = mc._pasoDesfase || 0;
    if (!d) return;
    // Si la y no es la que dejamos pintada, es que alguien movio al jugador por su cuenta
    // (game.tp, un respawn, un alPisar…): ese desfase ya no significa nada y se tira.
    // Se repone la y GUARDADA, no pos[1]+d: sumar y restar el desfase no da exactamente el mismo
    // float, y ese pelo de diferencia acabaria en la colision. Asi la fisica es idéntica al bit.
    if (mc._pasoY === mc.pos[1]) mc.pos[1] = mc._pasoReal; else mc._pasoDesfase = 0;
  }

  // El escalon se mide DONDE SE DA: dentro de mcMoveAxis, cuyo unico efecto sobre la y es el
  // `p[1] += h` del auto-escalon (app.js:4919), y cuyos dos unicos llamantes son las dos lineas
  // horizontales de mcUpdate. Deducirlo al final del frame comparando la y NO funciona, y fue el
  // primer intento: en app.js la gravedad va ANTES del horizontal, asi que el frame del escalon
  // termina con vel[1]=0 y `ny === p[1]`, no choca y deja **onGround = false** (app.js:5097). Una
  // guarda que pidiese «estar en el suelo» se apaga justo en el unico frame que hay que suavizar —
  // el dueño no notaba ninguna diferencia entre pasoSuave(0) y pasoSuave(1000). Midiendo aqui no hay
  // heuristica: saltar y trepar no pasan por mcMoveAxis, asi que no se cuelan solos.
  function envolverMoveAxis() {
    if (typeof mcMoveAxis !== 'function') return false;
    var orig = mcMoveAxis._paso ? mcMoveAxis._orig : mcMoveAxis;
    var env = function (ai, target) {
      var y0 = mc.pos[1];
      orig(ai, target);
      var d = mc.pos[1] - y0;
      if (d > 0) mc._pasoSubido = (mc._pasoSubido || 0) + d;
    };
    env._paso = VERSION;
    env._orig = orig;
    window.mcMoveAxis = env;
    return true;
  }

  // ── Solidez de los seguidores: tres envoltorios, cero cambios en app.js ─────────────────────
  //
  // Una pieza movida por matriz se DIBUJA en su sitio nuevo (el culling y la sombra del sol ya
  // transforman por s.model, app.js:5249 y 4758) pero la colision fina no: sondea el bitset con base
  // bx = s.ox*T (app.js:5064). Sin esto la pieza se veria perseguirte y la atravesarias, y ademas
  // dejaria un muro invisible en el ancla. Como TODO el sondeo fino del motor entra por dos globales
  // — mcStructColl y mcFineBoxHit — se arregla envolviendo esas dos, y de paso vale para el jugador,
  // para el rayo de romper y para pegar bloques.
  //
  // Salida rapida: si no hay ninguna desplazada (nDesplazados = 0, el caso normal) los envoltorios
  // devuelven lo del original sin mirar nada. mcCollides se llama varias veces por frame y por eje.
  // ── Atravesable: se ve, da sombra, se apunta y se rompe, pero el jugador la cruza ───────────
  // Devuelve la MISMA forma que produce un .vox.json con "atravesable" (Fase 6): bits = ceros
  // (colision) y bitsAim = la ocupacion real (apuntar / romper / rayos-X). Por eso las dos vias
  // convergen y app.js no necesita saber cual de las dos vino: ya sabe leer esto.
  //
  // ⚠️ bits NUNCA null: mcStructColl devuelve null si la pieza no tiene bits, y entonces la hierba
  // desapareceria tambien del apuntado -- no se podria ni romper la que acabas de definir.
  var clonesAtrav = {};   // 'clave|rot' -> { de: g original, g: clon }
  function sinChoque(g, clave, rot) {
    if (!g || !g.bits) return g;
    var cfg = tabla[clave];
    if (!cfg || !cfg.atravesable) return g;              // el caso normal: ni un objeto de mas
    var ck = clave + '|' + rot, hecho = clonesAtrav[ck];
    // Se invalida comparando el ORIGINAL, no la longitud: un mcRestampAll rehace meshRot y `g` pasa a
    // ser otro objeto (otro tamaño, otro atlas), asi que el array de ceros cacheado ya no vale.
    if (hecho && hecho.de === g) return hecho.g;
    var clon = Object.create(g);   // hereda fdim/vbo/count en vivo; solo se pisan los dos bitsets
    clon.bits = new Uint8Array(g.bits.length);
    clon.bitsAim = g.bitsAim || g.bits;
    clonesAtrav[ck] = { de: g, g: clon };
    return clon;
  }

  function envolverColision() {
    if (typeof mcStructColl !== 'function' || typeof mcFineBoxHit !== 'function') return false;
    var origColl = mcStructColl._seguir ? mcStructColl._orig : mcStructColl;
    var origBox = mcFineBoxHit._seguir ? mcFineBoxHit._orig : mcFineBoxHit;
    var origAt = (typeof mcStructAt === 'function') ? (mcStructAt._seguir ? mcStructAt._orig : mcStructAt) : null;

    // 1. El ancla deja de ser solida en cuanto la pieza se va. Si no, quedaria un bloque de aire con
    //    el que chocas donde la pieza ESTABA, que es justo el bug que la gente llama «fantasma».
    // Y con ella se van las EXTREMIDADES de un agente articulado, que no son solidas nunca: el rig
    // las GIRA y estos envoltorios solo saben trasladar, asi que su caja no acompañaria al dibujo —
    // y una caja invisible donde no hay brazo es peor que ningun brazo. El agente choca por su
    // raiz, que si lleva _sig y si es solida donde se la ve.
    var envColl = function (s) {
      if (s === yoSondeando) return null;          // sondeandose a si misma: ver chocaEstructura
      if (s._rig && !s._rigRaiz) return null;
      if (desplazada(s)) return null;
      return sinChoque(origColl(s), s.key, s.rot | 0);
    };

    // 2. Y aparece donde esta: se resta el desplazamiento a la caja de consulta y se prueba el mismo
    //    bitset. Redondeado a voxel fino (1/16): sondear medio voxel no significa nada, y asi la
    //    pieza es solida en celdas enteras igual que cuando esta quieta.
    var golpe = function (fx0, fy0, fz0, fx1, fy1, fz1) {
      var T = MC_T, ests = mc.structures;
      for (var i = 0; i < ests.length; i++) {
        var s = ests[i];
        if (!desplazada(s)) continue;
        var cAtr = tabla[s.key]; if (cAtr && cAtr.atravesable) continue;
        var g = origColl(s); if (!g) continue;
        var q = s._sig, d = g.fdim;
        var bx = s.ox * T + Math.round(q.x * T), by = s.oy * T + Math.round(q.y * T), bz = s.oz * T + Math.round(q.z * T);
        var x0 = Math.max(fx0 - bx, 0), x1 = Math.min(fx1 - bx, d[0] - 1); if (x0 > x1) continue;
        var y0 = Math.max(fy0 - by, 0), y1 = Math.min(fy1 - by, d[1] - 1); if (y0 > y1) continue;
        var z0 = Math.max(fz0 - bz, 0), z1 = Math.min(fz1 - bz, d[2] - 1); if (z0 > z1) continue;
        for (var y = y0; y <= y1; y++) for (var z = z0; z <= z1; z++) {
          var row = (y * d[2] + z) * d[0];
          for (var x = x0; x <= x1; x++) if (g.bits[row + x]) return true;
        }
      }
      return false;
    };
    var envBox = function (fx0, fy0, fz0, fx1, fy1, fz1) {
      if (origBox(fx0, fy0, fz0, fx1, fy1, fz1)) return true;
      if (!nDesplazados) return false;
      return golpe(fx0, fy0, fz0, fx1, fy1, fz1);
    };

    // 3. Y se rompe donde se la ve. mcStructAt es lo que mira el clic de romper (app.js:5912): sin
    //    esto habria que apuntar al ancla vacia para borrar una pieza que esta a diez bloques.
    var envAt = origAt && function (px, py, pz) {
      var s = origAt(px, py, pz);
      if (s || !nDesplazados) return s;
      var T = MC_T, fx = Math.floor(px * T), fy = Math.floor(py * T), fz = Math.floor(pz * T);
      var ests = mc.structures;
      for (var i = 0; i < ests.length; i++) {
        var e = ests[i];
        if (!desplazada(e)) continue;
        var g = origColl(e); if (!g) continue;
        var q = e._sig, d = g.fdim;
        var lx = fx - (e.ox * T + Math.round(q.x * T)), ly = fy - (e.oy * T + Math.round(q.y * T)), lz = fz - (e.oz * T + Math.round(q.z * T));
        if (lx < 0 || ly < 0 || lz < 0 || lx >= d[0] || ly >= d[1] || lz >= d[2]) continue;
        if ((g.bitsAim || g.bits)[(ly * d[2] + lz) * d[0] + lx]) return e;
      }
      return null;
    };

    envColl._seguir = VERSION; envColl._orig = origColl; window.mcStructColl = envColl;
    envBox._seguir = VERSION; envBox._orig = origBox; window.mcFineBoxHit = envBox;
    if (envAt) { envAt._seguir = VERSION; envAt._orig = origAt; window.mcStructAt = envAt; }
    return true;
  }

  // ── El clic izquierdo sobre un agente: golpe, no roto ─────────────────────────
  // mcBreak (app.js) marcha el rayo fino desde el ojo y RETIRA ENTERA la primera estructura que
  // toca; una pieza de agente es `efimera`, asi que ademas se iba sin historial y sin guardar. Y
  // como la unica pieza solida de un rig es su RAIZ (las extremidades no tienen colision, ver
  // envColl), el clic que se llevaba «el cuerpo» dejaba al bicho sin raiz y quedaban cinco miembros
  // congelados en el aire: es el «desaparece el bloque y el zombie deja de funcionar».
  //
  // Ahora ese clic es un GOLPE. Se envuelve mcBreak — ni una linea de app.js (§0) — repitiendo SU
  // MISMO rayo (mismo ojo, mismo paso de 1/16, mismo alcance) para saber que gana: si lo primero que
  // toca es una pieza de agente, el clic se COME ahi, asi que tampoco se rompe el terreno de detras.
  // Cualquier otra cosa (terreno, decorado, una efimera suelta) va al original y se rompe como
  // siempre. Para retirar un agente esta game.esqueletos.quitar(id).
  function piezaDeAgenteEnLaMira() {
    if (typeof mc === 'undefined' || !mc.pos || !mc.structures || !mc.structures.length) return null;
    if (typeof mcStructAt !== 'function' || typeof mcFineSolidAt !== 'function') return null;
    var T = MC_T, esc = num(mc.scale, 1);
    var oy = mc.pos[1] + (typeof MC_EYE === 'number' ? MC_EYE : 1.62) * esc;
    var cp = Math.cos(mc.pitch || 0);
    var dx = -Math.sin(mc.yaw || 0) * cp, dy = Math.sin(mc.pitch || 0), dz = -Math.cos(mc.yaw || 0) * cp;
    var maxd = (typeof mcReach === 'function') ? mcReach() : 6 * esc, paso = 1 / T;
    for (var t = paso; t <= maxd; t += paso) {
      var px = mc.pos[0] + dx * t, py = oy + dy * t, pz = mc.pos[2] + dz * t;
      if (mcFineSolidAt(Math.floor(px * T), Math.floor(py * T), Math.floor(pz * T))) {
        var s = mcStructAt(px, py, pz);
        if (s) return s._rig ? s : null;                  // lo PRIMERO que se toca manda
      }
      if (py >= 0 && typeof mcSolid === 'function'
        && mcSolid(Math.floor(px), Math.floor(py), Math.floor(pz))) return null;
    }
    return null;
  }
  function envolverGolpe() {
    if (typeof mcBreak !== 'function') return false;
    if (mcBreak._golpe === VERSION) return true;
    var orig = mcBreak._golpe ? mcBreak._orig : mcBreak;
    var env = function () {
      var s = piezaDeAgenteEnLaMira();
      if (s && s._rig && !s._rig.quitado) { golpear(s._rig, 0); return; }
      return orig.apply(this, arguments);
    };
    env._golpe = VERSION; env._orig = orig; window.mcBreak = env;
    return true;
  }

  function suavizarPaso(dt) {
    var d = mc._pasoDesfase || 0;
    var subido = mc._pasoSubido || 0;                   // lo que el auto-escalon levanto este frame
    mc._pasoSubido = 0;
    var tope = PASO * (mc.scale || 1);
    if (TAU_PASO > 0) {
      d += subido;                                      // el ojo se queda donde estaba
      d *= Math.exp(-dt / TAU_PASO);                    // independiente de los fps
      if (d > tope) d = tope;                           // nunca mas de un escalon por detras
      if (d < 1 / 512) d = 0;                           // menos de eso no se ve: se cierra en seco
    } else {
      d = 0;
    }
    mc._pasoDesfase = d;
    if (d) { mc._pasoReal = mc.pos[1]; mc.pos[1] -= d; mc._pasoY = mc.pos[1]; }
  }

  // ── Deslizamiento: seguir patinando al soltar las teclas (el hielo de Minecraft) ─────────────
  // Esto NO se puede hacer dejando puesta mc.vel, y ahi esta el motivo de que el patinaje se conduzca
  // a mano: en el suelo app.js:5094 REESCRIBE vel[0]/vel[2] cada frame desde las teclas, y sin teclas
  // los pone a cero ANTES de mover. Cualquier velocidad que dejemos puesta se borra al frame siguiente
  // sin haber movido nada (por eso 'inercia' es de RAPIDEZ y no de patinaje). Asi que aqui se guarda
  // la marcha llevada (mc._deslizVel), decae con exp(-dt/tau) —igual a 30 que a 120 fps— y se avanza
  // con el MISMO mcMoveAxis que usa app.js, para que muros y auto-escalon se comporten identico.
  // El estado vive en mc y no en una closure para que reejecutar el snippet no te congele a medio derrape.
  // ¿Se esta pilotando? Las mismas cuatro teclas que lee app.js:5086-5089 para fijar la velocidad.
  function hayRumbo() {
    var k = mc.keys || {};
    return !!(k['w'] || k['a'] || k['s'] || k['d']);
  }
  function deslizar(dt) {
    if (!mc.pos || !mc.vel) return;
    var llev = mc._deslizVel;
    if (agarradoPrev) { mc._deslizVel = null; return; }    // colgado de una escalera no se patina
    if (!mc.onGround) {
      // En el aire app.js ya conserva la inercia el solo (air-strafe, app.js:5096): no hay nada que
      // conducir. Solo se sigue la velocidad real para que al aterrizar se retome el derrape.
      if (llev) { llev[0] = mc.vel[0]; llev[1] = mc.vel[2]; }
      return;
    }
    var pie = pieEn();
    var tau = (pie && pie.m && pie.m.cfg && pie.m.cfg.deslizamiento) || 0;
    // Con una tecla de rumbo pulsada MANDA app.js: ya ha fijado vel y ya ha MOVIDO al jugador este
    // frame, asi que empujar aqui ademas seria moverlo DOS VECES. Eso se notaba como un aceleron al
    // salir de una pista rapida con W pulsada (el dueño lo vio y lo achaco al roce): durante los
    // ~3·TAU_ROCE del derrape ibas a marcha normal MAS la marcha guardada. Encima del bloque se
    // memoriza la marcha para cuando sueltes; fuera se olvida, que ahi ya no hay nada que patinar.
    if (hayRumbo()) {
      mc._deslizVel = tau > 0 ? [mc.vel[0], mc.vel[2]] : null;
      return;
    }
    if (!llev) return;             // nunca se CREA marcha fuera del hielo: andar normal no se toca
    // Ya fuera del hielo el derrape no se corta en seco (te sales patinando) pero dura un suspiro:
    // TAU_ROCE. Encima del hielo manda el tau del propio bloque.
    var k = Math.exp(-dt / (tau > 0 ? tau : TAU_ROCE));
    var nx = llev[0] * k, nz = llev[1] * k;
    if (Math.hypot(nx, nz) < DESLIZ_MIN) { mc._deslizVel = null; return; }
    var p = mc.pos;
    if (nx) { var x0 = p[0]; mcMoveAxis(0, x0 + nx * dt); if (p[0] === x0) nx = 0; }   // muro: ese eje muere
    if (nz) { var z0 = p[2]; mcMoveAxis(2, z0 + nz * dt); if (p[2] === z0) nz = 0; }
    if (!nx && !nz) { mc._deslizVel = null; return; }
    mc._deslizVel = [nx, nz];
    mc.vel[0] = nx; mc.vel[2] = nz;   // asi saltar (o pisar un trampolin) se lleva la marcha del derrape
  }

  // ── Parkour: colgarse de un canto y trepar ──────────────────────────────────────────────────
  //
  // Lo que app.js sabe hacer hoy es el salto de Minecraft (mc.vel[1] = 8·√escala, app.js:5929) y el
  // auto-escalon de medio bloque (MC_STEP = 0.6, app.js:5750). Un saliente a 3 de altura es
  // inalcanzable: se salta, se choca contra la pared y se cae. Esto añade lo de los juegos de
  // escalada: si el salto se queda corto y el ESPACIO sigue pulsado, el jugador se queda COLGADO del
  // canto; desde ahi W sube en una curva suave hasta ponerse de pie encima, y A/D se desplazan por el
  // borde. El agarre es de UN frame y a coste casi nulo cuando no hay nada delante.
  //
  // Tres detalles del ORDEN de ejecucion mandan sobre el diseño entero, y ninguno es opinable:
  //
  //  (A) mcUpdate ARRANCA desatascando (app.js:5898): si el jugador colisiona, mcUnstick lo sube en
  //      pasos de 1/16 hasta el primer hueco y le pone onGround = true. Una pose de colgado que
  //      solape la pared AUNQUE SEA 1e-9 se convertiria al frame siguiente en un trepado instantaneo
  //      falso. Por eso mientras dura el parkour NO se llama a orig(dt) en absoluto —asi mcUnstick ni
  //      corre— y ademas la pose se valida con mcCollides y se RETRAE por la normal hasta que quepa;
  //      si nunca cabe, no hay agarre. Lo segundo sigue importando para el frame en que se suelta.
  //
  //  (B) La subida es un movimiento GUIONIZADO: se escribe mc.pos a mano y la fisica no corre. La
  //      curva pasa por la esquina del canto y mcMoveAxis/gravedad la desharian. Lo que si se sigue
  //      llamando es seguirObjetivos/mirarObjetivos/esqueletosPaso: el mundo no se congela mientras
  //      trepas, solo el jugador deja de estar pilotado por la fisica.
  //
  //  (C) El envoltorio recibe el dt CRUDO. mcUpdate acota a 0,05 POR DENTRO (app.js:5894), asi que
  //      saltarse orig(dt) es saltarse tambien el tope: con la pestaña en segundo plano llegan dt de
  //      varios segundos y la subida se completaria de un tiron. El envoltorio pone su propio tope.
  //
  // El estado vive en mc._parkour y no en un closure por lo mismo que mc._pasoDesfase: reejecutar el
  // snippet a media escalada no debe dejar al jugador congelado en el aire.
  var PK_ACT = true;      // encendido por defecto (decision del dueño: «cualquier borde solido»)
  var PK_HMIN = 1.5;      // altura MINIMA del canto sobre los pies, en unidades de jugador (×escala).
                          // Por encima de lo que se alcanza saltando: h = v²/2g = (8√s)²/44 = 1,4545·s.
                          // Asi un bloque de 1 se sigue subiendo de un salto y no se queda uno colgado.
  var PK_HMAX = 2.2;      // ...y hasta donde llega el brazo por encima de la cabeza (el jugador mide 1,8)
  var PK_CAIDA = 0;       // velocidad de caida MINIMA para permitir el agarre (u/s); 0 = basta con bajar
  var PK_VLAT = 1.6;      // desplazamiento lateral colgado, u/s a escala 1
  var PK_DUR = 0.45;      // segundos que dura la subida
  var PK_ALC = 0.45;      // cuanto se asoma el sondeo mas alla del cuerpo (como ALCANCE, el de escaleras)
  var PK_ENFRIA = 0.25;   // veda tras coronar (s): sin esto se re-agarra al canto que acaba de subir
  var PK_RETRAE = 8;      // pasos de 1/16 que puede retraerse la pose de colgado antes de rendirse
  var PK_CALADO = 1.2;    // cuanto cuerpo tiene que quedar POR DEBAJO del canto (u. de jugador). Lo
                          // que sobre puede asomar por encima: agarrarse cerca del punto alto del
                          // salto no es un descuelgue muerto, y forzar ahi la pose canonica era el
                          // tiron hacia abajo que reporto el dueño.
  var PK_ACOMODO = 0.06;  // tau del acomodo (s): lo que quede entre donde te agarraste y la pose se
                          // consume con un decaimiento exponencial, nunca de un frame a otro
  var pkMotivo = 'sin sondear';   // POR QUE no engancha; es lo que lee game.parkour.estado()

  // Solidez a resolucion FINA mirando los DOS sitios donde vive el mundo: la rejilla de bloques
  // (assets macizos, 16³) y las estructuras de 1/16. Sondear solo la rejilla es ver medio mundo.
  function pkSolido(x, fy, z) {
    if (typeof mcSolid === 'function' && mcSolid(Math.floor(x), Math.floor(fy / MC_T), Math.floor(z))) return true;
    if (mc.structures && mc.structures.length && typeof mcFineSolidAt === 'function')
      return !!mcFineSolidAt(Math.floor(x * MC_T), fy, Math.floor(z * MC_T));
    return false;
  }
  // Un canto se describe con: eje de avance (0 = x, 2 = z), signo, coordenada de la CARA de la pared y
  // altura del canto. La coordenada del OTRO eje ('lat') es lo unico que mueve el desplazamiento lateral.
  function pkPunto(b, lat, along) {
    var o = [0, 0, 0];
    o[b.eje] = along;
    o[b.eje === 0 ? 2 : 0] = lat;
    return o;
  }
  // 'y' es la altura a la que se cuelga. Sin ella se usa la CANONICA (cabeza al ras del canto), que
  // es la unica que garantiza que el cuerpo entero quede por debajo y por tanto que nada de lo que
  // haya encima del canto pueda solapar la pose. Pero imponerla siempre era el tiron: si te agarras
  // cerca del punto alto del salto, tu cuerpo esta MAS ARRIBA que eso y bajarlo de un frame a otro
  // se ve como una sacudida. Se cuelga donde estabas y lo que asome por encima lo valida mcCollides
  // igual que cualquier otra pose; la canonica queda de red de seguridad (ver pkBuscar).
  function pkPose(b, lat, hueco, esc, y) {
    var o = pkPunto(b, lat, b.face - b.sgn * (HW * esc + hueco));
    o[1] = (y === undefined || y === null) ? b.yTop - PH * esc : y;
    return o;
  }
  function pkDestino(b, lat, esc) {
    var o = pkPunto(b, lat, b.face + b.sgn * (HW * esc + 2 / MC_T));   // el cuerpo entero pasado el canto
    o[1] = b.yTop;
    return o;
  }
  // Devuelve el HUECO (separacion a la pared) con el que el agarre es valido en 'lat', o -1. Es el
  // MISMO test para el agarre inicial y para cada sub-paso lateral: en cuanto deja de cumplirse, se
  // para ahi. Lo caro (mcCollides) va al final, detras de las lecturas de rejilla.
  function pkValido(b, lat, esc, y) {
    var fy = Math.round(b.yTop * MC_T) - 1;              // ultimo voxel fino SOLIDO del canto
    var hw = HW * esc;
    // 1) ¿sigue siendo un CANTO? solido justo debajo y aire justo encima, en la vertical de la cara
    var q = pkPunto(b, lat, b.face + b.sgn / (2 * MC_T));
    if (!pkSolido(q[0], fy, q[2])) { pkMotivo = 'el canto ya no está ahí'; return -1; }
    if (pkSolido(q[0], fy + 1, q[2])) { pkMotivo = 'hay pared encima del canto'; return -1; }
    // 2) APOYO bajo las CUATRO esquinas de la huella de aterrizaje. Sin esto, un labio de 1/16 pasa el
    //    test del canto y te deja de pie sobre el aire.
    var d = pkDestino(b, lat, esc), ins = hw - 1 / (4 * MC_T);
    for (var sx = -1; sx <= 1; sx += 2) for (var sz = -1; sz <= 1; sz += 2)
      if (!pkSolido(d[0] + sx * ins, fy, d[2] + sz * ins)) { pkMotivo = 'sin apoyo bajo la huella'; return -1; }
    // 3) ¿cabe de pie ARRIBA? mcCollides mira el alto entero (PH·escala): un vano de 1 lo rechaza.
    if (mcCollides(d[0], d[1], d[2])) { pkMotivo = 'no cabe de pie arriba'; return -1; }
    // 4) y la pose de colgado no puede solapar NADA — ver (A). Se retrae por la normal hasta que quepa.
    for (var i = 0; i <= PK_RETRAE; i++) {
      var hueco = 1 / (2 * MC_T) + i / MC_T;
      var h = pkPose(b, lat, hueco, esc, y);
      if (!mcCollides(h[0], h[1], h[2])) return hueco;
    }
    pkMotivo = 'la pose de colgado choca';
    return -1;
  }
  // Busca un canto delante del jugador. La direccion se ENCAJA AL EJE (la componente mayor del yaw):
  // el mundo es de cubos y un agarre en diagonal contra una esquina no se sostiene ni se dibuja bien.
  function pkBuscar(esc) {
    if (!mc.grid || !mc.pos) { pkMotivo = 'fuera del Mundo'; return null; }
    var p = mc.pos;
    // Una coordenada NaN haria que Math.floor(NaN) se saltase los bucles de mcCollides: «no hay
    // colision en ninguna parte» y caida infinita. Se corta aqui, que es donde entra el dato.
    if (!isFinite(p[0]) || !isFinite(p[1]) || !isFinite(p[2])) { pkMotivo = 'coordenada no finita'; return null; }
    var fx = -Math.sin(mc.yaw), fz = -Math.cos(mc.yaw);
    var eje = Math.abs(fx) >= Math.abs(fz) ? 0 : 2;
    var sgn = (eje === 0 ? fx : fz) >= 0 ? 1 : -1;
    var hw = HW * esc;
    // Suelo de altura: SIEMPRE por encima de lo que app.js sube solo. 'inc' es el mismo paso fino del
    // auto-escalon (app.js:5754); sin ese margen el parkour y el escalon se pelearian por el mismo
    // bloque y un bordillo daria un agarre en vez de una zancada.
    var stepH = PASO * esc, inc = Math.max(1 / MC_T, stepH / 12);
    var hmin = Math.max(PK_HMIN * esc, stepH + inc), hmax = PK_HMAX * esc;
    if (hmax <= hmin) { pkMotivo = 'alturaMax por debajo del auto-escalón'; return null; }
    var fyHi = Math.floor((p[1] + hmax) * MC_T), fyLo = Math.ceil((p[1] + hmin) * MC_T);
    var paso = 1 / MC_T, n = Math.min(32, Math.ceil(PK_ALC * esc * MC_T));
    var lat0 = eje === 0 ? p[2] : p[0], nlat = Math.min(16, Math.ceil(hw * MC_T));
    pkMotivo = 'no hay ningún canto delante';
    for (var i = 0; i <= n; i++) {
      var d = hw + paso + i * paso;
      var qx = p[0] + (eje === 0 ? sgn * d : 0), qz = p[2] + (eje === 2 ? sgn * d : 0);
      if (pkSolido(qx, fyHi + 1, qz)) continue;          // la pared sigue por encima del alcance
      var fy = -1;
      for (var y = fyHi; y >= fyLo; y--) if (pkSolido(qx, y, qz)) { fy = y; break; }
      if (fy < 0) continue;
      // Como se barre de CERCA a LEJOS en pasos de 1/16, la primera columna solida es la de la cara:
      // su borde interior es la cara de la pared, sin adivinar nada.
      var cara = Math.floor((eje === 0 ? qx : qz) * MC_T);
      var b = { eje: eje, sgn: sgn, yTop: (fy + 1) / MC_T, face: (sgn > 0 ? cara : cara + 1) / MC_T };
      // Ayuda de puntería: si en la vertical exacta del jugador la huella no apoya (llegaste medio
      // bloque descentrado), se prueban 1/16 a cada lado hasta medio cuerpo. Es lo mismo que haria el
      // desplazamiento lateral nada mas colgarse, pero sin obligar al dueño a pelearse con A/D.
      // A que altura se cuelga: A LA QUE ESTAS, que es la unica que no da tiron. El unico tope es
      // que quede PK_CALADO de cuerpo por debajo del canto (si no, con un alturaMin muy bajo te
      // «colgarias» de las rodillas). Por abajo no hace falta tope: el sondeo ya lo acota a hmax.
      var yCanon = b.yTop - PH * esc, yCol = Math.min(p[1], b.yTop - PK_CALADO * esc);
      for (var j = 0; j <= nlat; j++) {
        for (var s2 = -1; s2 <= 1; s2 += 2) {
          var lat = lat0 + s2 * j / MC_T, yh = yCol;
          var hueco = pkValido(b, lat, esc, yh);
          // Si a esa altura el cuerpo choca con algo de encima del canto, se reintenta con la pose
          // canonica, que cabe siempre por debajo: antes un acomodo suave que perder el agarre.
          if (hueco < 0 && yCol > yCanon) { yh = yCanon; hueco = pkValido(b, lat, esc, yh); }
          if (hueco >= 0) { b.lat = lat; b.hueco = hueco; b.esc = esc; b.y = yh; return b; }
          if (j === 0) break;                            // el centro solo se prueba una vez
        }
      }
    }
    return null;
  }
  function pkSoltar(motivo) { mc._parkour = null; pkMotivo = motivo; }
  // ¿A que lado cae la tecla D? El eje libre es el perpendicular al de avance, y el signo se FIJA al
  // agarrarse: reevaluarlo por frame da bandazos justo cuando miras a lo largo de la pared, porque
  // ahi el producto escalar con el 'right' de la camara (app.js:5901) cruza el cero.
  function pkLado(eje) {
    var d = eje === 0 ? -Math.sin(mc.yaw) : Math.cos(mc.yaw);
    return d >= 0 ? 1 : -1;
  }
  function pkLateral(pk, dir, dt, esc) {
    var total = PK_VLAT * esc * dt, paso = 1 / MC_T, hecho = 0;
    for (var i = 0; i < 64 && hecho < total; i++) {
      var avance = Math.min(paso, total - hecho);
      var lat = pk.lat + dir * avance;
      var hueco = pkValido(pk, lat, esc, pk.y);          // a LA MISMA altura: el shimmy no sube ni baja
      if (hueco < 0) break;                              // fin del canto, esquina o hueco: se para aqui
      pk.lat = lat; pk.hueco = hueco; hecho += avance;
    }
  }
  // Intento de agarre. Corre DESPUES de la fisica del frame, asi que onGround/vel son los de verdad.
  function pkIntento(dt) {
    if (mc._parkour) return true;
    if (mc._pkEnfria > 0) { mc._pkEnfria -= dt; if (mc._pkEnfria > 0) { pkMotivo = 'enfriando'; return false; } }
    if (!PK_ACT) { pkMotivo = 'apagado (game.parkour.activo = false)'; return false; }
    if (!mc.grid || !mc.pos || !mc.vel) return false;
    var k = mc.keys || {};
    if (!k[' ']) { pkMotivo = 'sin espacio pulsado'; return false; }
    // Solo EN EL AIRE y BAJANDO: asi el agarre no compite con el salto ni con el auto-escalon y solo
    // aparece cuando el salto ya se ha quedado corto, que es justo lo que pidio el dueño.
    if (mc.onGround) { pkMotivo = 'de pie en el suelo'; return false; }
    if (mc.vel[1] >= -PK_CAIDA) { pkMotivo = 'todavía subiendo (el agarre solo entra al caer)'; return false; }
    var esc = mc.scale || 1;
    var b = pkBuscar(esc);
    if (!b) return false;
    var p = mc.pos, antes = [p[0], p[1], p[2]];
    var pose = pkPose(b, b.lat, b.hueco, esc, b.y);
    // El frame del agarre NO mueve al jugador: se guarda la diferencia entre donde estaba y la pose
    // y se le suma entera, asi que visualmente se queda clavado donde saltaste. Esa diferencia es el
    // «acomodo» y se consume sola en los frames siguientes (pkPaso). Sin esto, aunque la altura ya
    // no de tiron, el enganche a la pared por XZ (hasta el alcance del sondeo) seguiria siendo seco.
    var des = [antes[0] - pose[0], antes[1] - pose[1], antes[2] - pose[2]];
    p[0] = antes[0]; p[1] = antes[1]; p[2] = antes[2];
    mc.vel[0] = 0; mc.vel[1] = 0; mc.vel[2] = 0;
    mc.onGround = false;
    mc._parkour = { st: 'colgado', eje: b.eje, sgn: b.sgn, face: b.face, yTop: b.yTop, lat: b.lat,
                    hueco: b.hueco, esc: esc, t: 0, dur: PK_DUR, lado: pkLado(b.eje),
                    y: b.y, des: des, esp: [p[0], p[1], p[2]] };
    agarradoPrev = false;      // colgado de un canto no se esta colgado de una escalera
    mc._deslizVel = null;      // ni patinando
    mc._pasoDesfase = 0; mc._pasoSubido = 0;   // ni a medio suavizar un escalon
    pkMotivo = 'colgado';
    return true;
  }
  // Un frame de parkour. Devuelve true si el parkour manda (y entonces la fisica NO corre, ver (B)).
  function pkPaso(dt) {
    var pk = mc._parkour;
    if (!pk) return false;
    var p = mc.pos;
