    // Sin argumento se los lleva a TODOS: boton de panico y, sobre todo, lo que hay que llamar antes
    // de reponer un agente para no dejar piezas sueltas por el mapa.
    quitar: function (rig) {
      if (rig === undefined || rig === null) {
        var n = 0, todos = esqueletos.slice();
        todos.forEach(function (r) { n += quitarEsqueleto(r); });
        console.log('game.esqueletos: retiradas ' + n + ' pieza(s) de ' + todos.length + ' agente(s).');
        return n;
      }
      if (typeof rig === 'number') {
        var enc = null;
        esqueletos.forEach(function (r) { if (r.id === rig) enc = r; });
        if (!enc) { console.warn('game.esqueletos.quitar: no hay ningún agente con id ' + rig + '.'); return 0; }
        rig = enc;
      }
      var m = quitarEsqueleto(rig);
      console.log('game.esqueletos: retiradas ' + m + ' pieza(s).');
      return m;
    },
    lista: esqueletos_,
    // El golpe a mano; el clic izquierdo sobre el bicho ya llama a esto. Sin direccion lo empuja
    // alejandolo del jugador, que es justo lo que hace el clic. fuerza 0 = la del documento.
    empujar: function (rig, fuerza, dx, dz) {
      var r = rigDe(rig);
      if (!r) { console.warn('game.esqueletos.empujar: no hay ning\u00fan agente con id ' + rig + '.'); return false; }
      if (dx === undefined && dz === undefined) return golpear(r, num(fuerza, 0));
      return empujarEsqueleto(r, num(fuerza, 0), num(dx, 0), num(dz, 0));
    },
    // Para DIBUJAR un agente fuera del Mundo (el panel del editor). Ver el comentario de preparar().
    preparar: prepararEsqueleto,
    // El editor avisa por aqui al re-guardar el dibujo de una pieza (app.js, mcRefreshSaved). docsCache
    // vive lo que vive esta ejecucion del snippet, asi que sin soltarlo el preview del panel seguia
    // montando el dibujo VIEJO aunque el fichero ya estuviera bien: «le doy a guardar y en el editor de
    // agentes sigo viendo el torso antiguo». Sin clave, se olvida todo.
    olvidarDibujo: function (clave) {
      if (clave === undefined) { docsCache = {}; return; }
      delete docsCache[clave];
    },
    pose: posarEsqueleto,
    _vivos: esqueletos
  };

  // El almacen de documentos, aparte de lo vivo a proposito (ver el comentario de agentesLista).
  game.agentes = {
    version: VERSION,
    lista: agentesLista,
    cargar: agenteCargar,
    guardar: agenteGuardar
  };

  // ── Comportamientos por defecto de este mundo ────────────────────────────────────────────────
  // Los datos estan ARRIBA DEL TODO (DEFECTOS), que es donde se buscan cuando solo se quiere cambiar
  // el mundo; aqui abajo solo se registran, porque es donde define() ya existe y tiene tabla y cache.
  Object.keys(DEFECTOS).forEach(function (k) { define(k, DEFECTOS[k]); });

  // Lo definido A MANO en la consola sobrevive a reejecutar el snippet: los cfg guardados ya estan
  // normalizados y define() los vuelve a normalizar con el codigo de ahora, asi que valen aunque la
  // version anterior tuviera otra forma.
  // Pero SOLO se hereda lo que esta ejecucion NO ha definido: lo que acabas de escribir aqui arriba
  // MANDA. Antes se heredaba todo encima y editar un define no servia absolutamente de nada — el
  // valor nuevo entraba (el define hasta avisaba del ×30) y dos lineas despues la tabla vieja lo
  // volvia a pisar, asi que lista() seguia enseñando el valor viejo y el mundo tampoco cambiaba.
  // Ojo al reves: BORRAR un define de aqui no lo quita, porque se hereda del run anterior. Para eso,
  // game.bloques.quitar('clave') o recargar la pestaña (al recargar no hay nada que heredar).
  var heredado = (previo && anterior && anterior._tabla) || null;
  if (heredado) {
    var claves = Object.keys(heredado).filter(function (k) { return !tabla[k]; });
    claves.forEach(function (k) { define(k, heredado[k]); });
    if (claves.length) console.log('game.bloques: heredados ' + claves.length + ' material(es) definidos a mano (los del snippet mandan).');
  }

  console.log('game.bloques ' + VERSION + ' · ' + Object.keys(tabla).length + ' material(es) con comportamiento'
    + (yaEstaba ? ' (envoltorio REINSTALADO: la física ahora lee esta tabla)' : '')
    + '. game.bloques.lista() / .info() · parkour ' + (PK_ACT ? 'ON' : 'off') + ' → game.parkour.estado()');

})();

// ==REDSTONE-ARRANQUE== (generado por redstone/make_snippets.js — no editar a mano)
// Carga redstone/redstone-arranque.js (motor + circuitos de serie). No se espera a propósito: no
// puede retrasar la entrada al Mundo, y el repaso del circuito se hace solo cuando termina.
(function () {
  fetch('/api/snippets/redstone-arranque', { cache: 'no-store' })
    .then(function (r) { return r.ok ? r.json() : null; })
    .then(function (d) {
      if (!d || !d.code) return;
      var AsyncFn = Object.getPrototypeOf(async function () {}).constructor;
      return new AsyncFn(d.code)();
    })
    .catch(function (e) { console.warn('redstone: arranque no cargado:', e && e.message); });
})();
// ==FIN-REDSTONE-ARRANQUE==
